}

func TestClassifyConnRefused(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := ln.Addr().String()
	ln.Close() // nothing listens on this port now

	resp, err := post(t, freshClient(2*time.Second), "http://"+addr)
	if err == nil {
		t.Fatal("dialing a closed port succeeded")
	}
	if got := Classify(resp, err, now); got.Class != ConnRefused {
		t.Errorf("closed port: %s (%v), want conn_refused", got.Class, err)
	}
}

func TestClassifyConnClosedBeforeResponse(t *testing.T) {
	srv := hijackServer(t, func(c net.Conn) { c.Close() })
	resp, err := post(t, freshClient(2*time.Second), srv.URL)
	if err == nil {
		t.Fatal("request succeeded on a closed connection")
	}
	if got := Classify(resp, err, now); got.Class != ConnReset {
		t.Errorf("closed before the response: %s (%v), want conn_reset", got.Class, err)
	}
}

func TestClassifyConnResetByPeer(t *testing.T) {
	srv := hijackServer(t, func(c net.Conn) {
		c.(*net.TCPConn).SetLinger(0) // close sends RST instead of FIN
		c.Close()
	})
	resp, err := post(t, freshClient(2*time.Second), srv.URL)
	if err == nil {
		t.Fatal("request succeeded on a reset connection")
	}
	if got := Classify(resp, err, now); got.Class != ConnReset {
		t.Errorf("reset by peer: %s (%v), want conn_reset", got.Class, err)
	}
}

// The response headers arrive, then the connection dies inside the body. The
// caller sees this as a read error and classifies that.
func TestClassifyUnexpectedEOFInBody(t *testing.T) {
	srv := hijackServer(t, func(c net.Conn) {
		io.WriteString(c, "HTTP/1.1 200 OK\r\nContent-Length: 100\r\n\r\nshort")
		c.Close()
	})
	resp, err := post(t, freshClient(2*time.Second), srv.URL)
	if err != nil {
		t.Fatal(err)
	}
	_, readErr := io.ReadAll(resp.Body)
	if !errors.Is(readErr, io.ErrUnexpectedEOF) {
		t.Fatalf("read error %v, want unexpected EOF", readErr)
	}
	if got := Classify(nil, readErr, now); got.Class != ConnReset {
		t.Errorf("truncated body: %s, want conn_reset", got.Class)
	}
}

// slowServer answers after the client has given up.
func slowServer(t *testing.T) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// The server notices a closed connection only once the body is read.
		io.Copy(io.Discard, r.Body)
		select {
		case <-r.Context().Done():
		case <-time.After(2 * time.Second):
		}
	}))
	t.Cleanup(srv.Close)
	return srv
}

func TestClassifyClientTimeout(t *testing.T) {
	srv := slowServer(t)
	resp, err := post(t, freshClient(50*time.Millisecond), srv.URL)
	if err == nil {
		t.Fatal("request succeeded past the client timeout")
	}
	if got := Classify(resp, err, now); got.Class != Timeout {
		t.Errorf("client timeout: %s (%v), want timeout", got.Class, err)
	}
}

func TestClassifyContextDeadline(t *testing.T) {
	srv := slowServer(t)
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, "POST", srv.URL, strings.NewReader("{}"))
	if err != nil {
		t.Fatal(err)
	}
	resp, err := freshClient(0).Do(req)
	if err == nil {
		resp.Body.Close()
		t.Fatal("request succeeded past the context deadline")
	}
	if got := Classify(nil, err, now); got.Class != Timeout {
		t.Errorf("context deadline: %s (%v), want timeout", got.Class, err)
	}
}

// Errors reach Classify wrapped by callers.
func TestClassifyWrappedErrors(t *testing.T) {
	cases := []struct {
		err  error
		want Class
	}{
		{context.DeadlineExceeded, Timeout},
		{fmt.Errorf("send: %w", context.DeadlineExceeded), Timeout},
		{io.EOF, ConnReset},
		{fmt.Errorf("send: %w", io.EOF), ConnReset},
		{fmt.Errorf("read: %w", io.ErrUnexpectedEOF), ConnReset},
	}
	for _, c := range cases {
		if got := Classify(nil, c.err, now); got.Class != c.want {
			t.Errorf("%v: %s, want %s", c.err, got.Class, c.want)
		}
	}
}

// ceiling is the documented upper bound: min(60s, 1s * 2^attempt).
func ceiling(attempt int) time.Duration {
	if attempt >= 6 {
		return 60 * time.Second
	}
	return time.Second << attempt
}

// Full jitter: uniform over [0, ceiling]. A fixed delay, or "equal jitter"
// that never goes below half the ceiling, fails the spread checks.
func TestBackoffFullJitter(t *testing.T) {
	rng := rand.New(rand.NewPCG(1, 2))
	for attempt := 0; attempt <= 8; attempt++ {
		top := ceiling(attempt)
		const n = 2000
		lo, hi, sum := time.Duration(math.MaxInt64), time.Duration(0), time.Duration(0)
		for range n {
			d := Backoff(attempt, rng)
			if d < 0 || d > top {
				t.Fatalf("attempt %d: delay %v outside [0, %v]", attempt, d, top)
			}
			lo, hi, sum = min(lo, d), max(hi, d), sum+d
		}
		if lo > top/10 {
			t.Errorf("attempt %d: smallest of %d delays is %v; full jitter reaches near 0", attempt, n, lo)
		}
		if hi < top*9/10 {
			t.Errorf("attempt %d: largest of %d delays is %v; full jitter reaches near %v", attempt, n, hi, top)
		}
		if mean := sum / n; mean < top*4/10 || mean > top*6/10 {
			t.Errorf("attempt %d: mean %v, want about %v", attempt, mean, top/2)
		}
	}
}

func TestBackoffLargeAttemptsStayCapped(t *testing.T) {
	rng := rand.New(rand.NewPCG(1, 2))
	for _, attempt := range []int{6, 30, 62, 63, 64, 65, 1000, math.MaxInt} {
		for range 200 {
			if d := Backoff(attempt, rng); d < 0 || d > 60*time.Second {
				t.Fatalf("attempt %d: delay %v outside [0, 60s] (shift overflow?)", attempt, d)
			}
		}
	}
}

// The random source is injected, so a seed fixes the sequence.
func TestBackoffIsDeterministic(t *testing.T) {
	a, b := rand.New(rand.NewPCG(7, 7)), rand.New(rand.NewPCG(7, 7))
	for attempt := range 10 {
		if x, y := Backoff(attempt, a), Backoff(attempt, b); x != y {
			t.Fatalf("attempt %d: %v and %v from the same seed", attempt, x, y)
		}
	}
}
package store

import (
	"context"
	"database/sql"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// The tables rivermigrate creates. Jobs cannot be inserted without them.
var riverTables = []string{"river_job", "river_leader", "river_queue", "river_migration"}

func missingRiverTables(t *testing.T, db *sql.DB) []string {
	t.Helper()
	var missing []string
	for _, tbl := range riverTables {
		var ok bool
		if err := db.QueryRow("SELECT to_regclass('public.' || $1) IS NOT NULL", tbl).Scan(&ok); err != nil {
			t.Fatal(err)
		}
		if !ok {
			missing = append(missing, tbl)
		}
	}
	return missing
}

// TestMigrateRunsRiver checks that Migrate creates the River tables after
// the goose migrations, and that a second run is a no-op.
func TestMigrateRunsRiver(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)
	if err := Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	if missing := missingRiverTables(t, db); len(missing) != 0 {
		t.Fatalf("after Migrate: River tables missing: %v", missing)
	}
	if pending, err := Pending(ctx, db); err != nil || pending {
		t.Fatalf("after Migrate: Pending = %v, %v; want false", pending, err)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("second run is not a no-op: %v", err)
	}
}

// TestPendingCoversRiver applies only the goose migrations. The database
// then has every app table but no River tables, so it is not ready: /readyz
// must not report ok for a database the worker cannot use.
func TestPendingCoversRiver(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)
	p, err := newMigrator(db)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := p.Up(ctx); err != nil {
		t.Fatal(err)
	}
	if missing := missingRiverTables(t, db); len(missing) != len(riverTables) {
		t.Fatalf("goose alone created River tables; this test no longer isolates them (missing %v)", missing)
	}
	if pending, err := Pending(ctx, db); err != nil || !pending {
		t.Fatalf("goose done, River missing: Pending = %v, %v; want true", pending, err)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("Migrate on a goose-only database: %v", err)
	}
	if pending, err := Pending(ctx, db); err != nil || pending {
		t.Fatalf("after Migrate: Pending = %v, %v; want false", pending, err)
	}
}

// TestTemplateHasRiver checks the template that make test builds, so every
// integration package gets River tables in its clone.
func TestTemplateHasRiver(t *testing.T) {
	url, _ := testdb.Seeded(t)
	db, err := sql.Open("pgx", url)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if missing := missingRiverTables(t, db); len(missing) != 0 {
		t.Fatalf("template clone lacks River tables: %v", missing)
	}
	if pending, err := Pending(context.Background(), db); err != nil || pending {
		t.Fatalf("template clone: Pending = %v, %v; want false", pending, err)
	}
}

