-- Campaigns, their revisions and audit trail, LLM call records, and messages.
-- State lists live in domains so each list is written once. Invariants the
-- state machine and the delivery worker rely on are enforced here too, so a
-- code bug fails loudly instead of corrupting data.

-- +goose Up
CREATE DOMAIN campaign_state AS text CHECK (VALUE IN (
    'draft', 'generating', 'in_review', 'generation_failed', 'approved',
    'sending', 'completed', 'completed_with_failures', 'rejected', 'cancelled'));

CREATE DOMAIN channel AS text CHECK (VALUE IN ('sms', 'email'));

-- "Retrying" is not a state: it is queued with attempts > 0.
CREATE DOMAIN message_state AS text CHECK (VALUE IN (
    'queued', 'sending', 'sent', 'failed', 'dead', 'skipped'));

-- Reason labels, shared by metrics and the dashboard. conn_refused is safe
-- to retry; timeout and conn_reset are ambiguous and safe only because every
-- retry carries the same idempotency key.
CREATE DOMAIN error_class AS text CHECK (VALUE IN (
    'rate_limited', 'server_error', 'timeout', 'conn_refused', 'conn_reset',
    'client_error', 'no_consent', 'cancelled'));

CREATE TABLE campaigns (
    id                   uuid           PRIMARY KEY DEFAULT gen_random_uuid(),
    brief                text           NOT NULL CHECK (char_length(brief) BETWEEN 1 AND 2000),
    state                campaign_state NOT NULL DEFAULT 'draft',
    -- Optimistic locking: every transition is UPDATE ... WHERE version = $v.
    version              integer        NOT NULL DEFAULT 0,
    current_revision_id  uuid,
    approved_revision_id uuid,
    approved_by          text,
    approved_at          timestamptz,
    -- The only source of links in copy ({{campaign_url}}). Code checks it is
    -- an https URL on an allowlisted domain.
    campaign_url         text           CHECK (char_length(campaign_url) <= 40),
    created_at           timestamptz    NOT NULL DEFAULT now(),
    updated_at           timestamptz    NOT NULL DEFAULT now(),
    -- An approval is all or nothing.
    CHECK ((approved_revision_id IS NULL) = (approved_by IS NULL)
       AND (approved_revision_id IS NULL) = (approved_at IS NULL)),
    -- Approved and later states always point at the approved revision.
    CHECK (state NOT IN ('approved', 'sending', 'completed', 'completed_with_failures')
        OR approved_revision_id IS NOT NULL)
);

-- Only valid revisions are stored: an LLM attempt or a human edit becomes a
-- revision after it passes validation (rule 7). Failed LLM attempts are kept
-- in llm_calls; rejected edits are answered with 422 and not stored.
CREATE TABLE campaign_revisions (
    id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id    uuid        NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    n              integer     NOT NULL CHECK (n >= 1),
    source         text        NOT NULL CHECK (source IN ('llm', 'human')),
    segment        jsonb       NOT NULL,
    sms_body       text        NOT NULL,
    email_subject  text        NOT NULL,
    email_body     text        NOT NULL,
    warnings       jsonb       NOT NULL DEFAULT '[]',
    audience_total integer     CHECK (audience_total >= 0),
    sms_eligible   integer     CHECK (sms_eligible >= 0),
    email_eligible integer     CHECK (email_eligible >= 0),
    created_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (campaign_id, n),
    -- Target of the composite foreign keys below.
    UNIQUE (id, campaign_id)
);

-- A campaign can only point at, or approve, its own revisions.
ALTER TABLE campaigns
    ADD FOREIGN KEY (current_revision_id, id) REFERENCES campaign_revisions (id, campaign_id),
    ADD FOREIGN KEY (approved_revision_id, id) REFERENCES campaign_revisions (id, campaign_id);

-- Audit trail: one row per state transition.
CREATE TABLE campaign_events (
    id          bigint         GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    campaign_id uuid           NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    from_state  campaign_state,
    to_state    campaign_state NOT NULL,
    actor       text           NOT NULL,
    reason      text           NOT NULL DEFAULT '',
    at          timestamptz    NOT NULL DEFAULT now()
);
CREATE INDEX campaign_events_campaign ON campaign_events (campaign_id, id);

-- One row per call to Claude, valid or not.
CREATE TABLE llm_calls (
    id                bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    campaign_id       uuid        NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    stage             text        NOT NULL CHECK (stage IN ('segment', 'content')),
    attempt           integer     NOT NULL CHECK (attempt >= 1),
    outcome           text        NOT NULL CHECK (outcome IN ('valid', 'invalid', 'refusal', 'max_tokens', 'transport_error')),
    error_class       error_class,
    stop_reason       text,
    model             text        NOT NULL,
    input_tokens      integer     CHECK (input_tokens >= 0),
    output_tokens     integer     CHECK (output_tokens >= 0),
    latency_ms        integer     NOT NULL CHECK (latency_ms >= 0),
    raw_output        text,
    validation_errors jsonb       NOT NULL DEFAULT '[]',
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX llm_calls_campaign ON llm_calls (campaign_id, id);

-- One row per recipient per channel. The id is the idempotency key sent to
-- the provider on every attempt (rule 10).
CREATE TABLE messages (
    id                  uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id         uuid          NOT NULL,
    revision_id         uuid          NOT NULL,
    user_id             uuid          NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    channel             channel       NOT NULL,
    state               message_state NOT NULL DEFAULT 'queued',
    attempts            integer       NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    last_error_class    error_class,
    last_error          text,
    next_attempt_at     timestamptz,
    provider_message_id text,
    sent_at             timestamptz,
    created_at          timestamptz   NOT NULL DEFAULT now(),
    updated_at          timestamptz   NOT NULL DEFAULT now(),
    -- The same person never gets the same campaign twice on one channel.
    UNIQUE (campaign_id, user_id, channel),
    -- The message belongs to a revision of its own campaign.
    FOREIGN KEY (revision_id, campaign_id) REFERENCES campaign_revisions (id, campaign_id),
    -- A sent message always has the provider's id and a send time.
    CHECK (state <> 'sent' OR (provider_message_id IS NOT NULL AND sent_at IS NOT NULL)),
    -- Failed, dead and skipped messages always say why.
    CHECK (state NOT IN ('failed', 'dead', 'skipped') OR last_error_class IS NOT NULL)
);
CREATE INDEX messages_campaign_state ON messages (campaign_id, state);
-- The dashboard's "Needs attention" panel scans unfinished messages.
CREATE INDEX messages_unfinished ON messages (state, updated_at) WHERE state IN ('queued', 'sending');

-- +goose Down
DROP TABLE messages;
DROP TABLE llm_calls;
DROP TABLE campaign_events;
ALTER TABLE campaigns DROP COLUMN current_revision_id, DROP COLUMN approved_revision_id;
DROP TABLE campaign_revisions;
DROP TABLE campaigns;
DROP DOMAIN error_class;
DROP DOMAIN message_state;
DROP DOMAIN channel;
DROP DOMAIN campaign_state;
package httpapi

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"log/slog"
	"net/http"
	"regexp"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// HTTP-level error codes, next to the validation codes.
const (
	codeUnauthorized = "unauthorized"
	codeBodyTooLarge = "body_too_large"
	codeInternal     = "internal"
)

const (
	maxBody      = 64 << 10
	queryTimeout = 3 * time.Second
)

// Server holds the API's dependencies.
type Server struct {
	Config  Config
	Pool    *pgxpool.Pool
	Schemas *schema.Set
	Log     *slog.Logger
	Now     func() time.Time // defaults to time.Now; tests pin it
}

// Handler builds the routes. It refuses to build an open API: with no token,
// ALLOW_UNAUTHENTICATED must have been set explicitly.
func (s *Server) Handler() (http.Handler, error) {
	if s.Config.AdminToken == "" && !s.Config.AllowUnauthenticated {
		return nil, ErrNoToken
	}
	if s.Now == nil {
		s.Now = time.Now
	}
	if s.Log == nil {
		s.Log = slog.New(slog.DiscardHandler)
	}
	api := http.NewServeMux()
	api.HandleFunc("POST /api/audience/count", s.count)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", s.healthz)
	mux.HandleFunc("GET /readyz", s.readyz)
	// Everything under /api is behind auth, unknown paths included, so an
	// unauthenticated caller cannot map the routes.
	mux.Handle("/api/", s.auth(api))
	return s.requestID(s.logRequests(mux)), nil
}

type ctxKey struct{}

var requestIDPattern = regexp.MustCompile(`^[A-Za-z0-9-]{1,64}$`)

// requestID keeps a well-formed X-Request-ID and replaces anything else, so
// a caller cannot inject log lines or huge values.
func (s *Server) requestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-ID")
		if !requestIDPattern.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, id)))
	})
}

func requestIDFrom(ctx context.Context) string {
	id, _ := ctx.Value(ctxKey{}).(string)
	return id
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

// logRequests logs method, path, status and duration. Never bodies, query
// strings or headers.
func (s *Server) logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		s.Log.Info("request", "method", r.Method, "path", r.URL.Path, "status", sw.status,
			"duration_ms", time.Since(start).Milliseconds(), "request_id", requestIDFrom(r.Context()))
	})
}

// auth checks the bearer token. Both sides are hashed first, so the
// constant-time compare also hides the token's length.
func (s *Server) auth(next http.Handler) http.Handler {
	if s.Config.AdminToken == "" {
		return next // only reachable with AllowUnauthenticated; Handler checks
	}
	want := sha256.Sum256([]byte(s.Config.AdminToken))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		got := sha256.Sum256([]byte(token))
		if !ok || subtle.ConstantTimeCompare(got[:], want[:]) != 1 {
			w.Header().Set("WWW-Authenticate", `Bearer realm="api"`)
			writeError(w, http.StatusUnauthorized, codeUnauthorized, "missing or invalid bearer token")
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (s *Server) healthz(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// readyz checks the database is reachable and fully migrated. Liveness
// (healthz) deliberately checks nothing outside the process.
func (s *Server) readyz(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
	defer cancel()
	notReady := func(reason string) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unavailable", "reason": reason})
	}
	if err := s.Pool.Ping(ctx); err != nil {
		notReady("database unreachable")
		return
	}
	db := stdlib.OpenDBFromPool(s.Pool) // goose needs database/sql; closing it leaves the pool open
	defer db.Close()
	if pending, err := store.Pending(ctx, db); err != nil || pending {
		notReady("migrations pending")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

type countResponse struct {
	segment.Counts
	AsOf     time.Time  `json:"as_of"`
	SeededAt *time.Time `json:"seeded_at"`
}

// count validates a segment rule and returns its audience size.
func (s *Server) count(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	doc, err := schema.Decode(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, codeBodyTooLarge, "body is larger than 64 KiB")
			return
		}
		writeError(w, http.StatusBadRequest, validation.InvalidJSON, err.Error())
		return
	}

	var res validation.Result
	body, isObject := doc.(map[string]any)
	switch {
	case !isObject:
		res.Error("", validation.InvalidType, `expected an object: {"rule": {...}}`)
	default:
		for k := range body {
			if k != "rule" {
				res.Error("/"+k, validation.UnknownProperty, `only "rule" is allowed`)
			}
		}
		if _, ok := body["rule"]; !ok {
			res.Error("/rule", validation.Required, `missing required key "rule"`)
		}
	}
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	rule, res := segment.Validate(s.Schemas, body["rule"])
	if !res.OK() {
		for i := range res.Errors {
			res.Errors[i].Path = "/rule" + res.Errors[i].Path
		}
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	asOf := s.Now().UTC().Truncate(time.Microsecond)
	counts, err := segment.CountAudience(ctx, s.Pool, rule, asOf)
	if err != nil {
		s.Log.Error("count failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	seededAt, err := store.SeededAt(ctx, s.Pool)
	if err != nil {
		s.Log.Error("reading seed_meta failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	writeJSON(w, http.StatusOK, countResponse{Counts: counts, AsOf: asOf, SeededAt: seededAt})
}

type errorBody struct {
	Errors []validation.Issue `json:"errors"`
}

func issues(list []validation.Issue) errorBody { return errorBody{Errors: list} }

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, issues([]validation.Issue{{Path: "", Code: code, Message: message}}))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
// Package httpapi is the HTTP API: auth, request ids, the audience count
// endpoint, and health checks.
package httpapi

import "errors"

// Config is read from the environment at startup.
type Config struct {
	// AdminToken is the bearer token every /api request must carry.
	AdminToken string
	// AllowUnauthenticated lets the API run without a token. Dev only, and
	// only when AdminToken is empty; a set token is always enforced.
	AllowUnauthenticated bool
	ListenAddr           string
}

// ErrNoToken is returned when neither a token nor the dev escape hatch is set.
var ErrNoToken = errors.New("ADMIN_TOKEN is not set; set it, or set ALLOW_UNAUTHENTICATED=true for local development only")

// ConfigFromEnv reads ADMIN_TOKEN, ALLOW_UNAUTHENTICATED and LISTEN_ADDR. It
// fails closed: no token and no explicit opt-out is an error, not an open API.
func ConfigFromEnv(getenv func(string) string) (Config, error) {
	c := Config{
		AdminToken:           getenv("ADMIN_TOKEN"),
		AllowUnauthenticated: getenv("ALLOW_UNAUTHENTICATED") == "true",
		ListenAddr:           getenv("LISTEN_ADDR"),
	}
	if c.ListenAddr == "" {
		c.ListenAddr = ":8080"
	}
	if c.AdminToken == "" && !c.AllowUnauthenticated {
		return Config{}, ErrNoToken
	}
	return c, nil
}

