// Package validation holds the result type every validator returns. The
// codes are stable: API clients, the LLM retry prompt and metric labels all
// depend on them, so add codes but never rename one.
package validation

// Codes for structural problems, mapped from JSON Schema keywords.
const (
	InvalidJSON     = "invalid_json"     // not exactly one JSON value
	Required        = "required"         // a required key is missing
	UnknownProperty = "unknown_property" // a key the schema does not define
	InvalidType     = "invalid_type"     // wrong JSON type
	UnknownValue    = "unknown_value"    // value outside an enum or const
	OutOfRange      = "out_of_range"     // number outside its minimum/maximum
	TooFew          = "too_few"          // array below minItems
	TooMany         = "too_many"         // array above maxItems
	DuplicateValue  = "duplicate_value"  // repeated array item
	TooShort        = "too_short"        // string below minLength
	TooLong         = "too_long"         // string above maxLength
	SchemaViolation = "schema_violation" // any other schema failure
)

// Codes for segment rules (docs/segment-rules.md).
const (
	OpNotAllowed    = "op_not_allowed"    // operator exists, but not for this field
	OpValueMismatch = "op_value_mismatch" // list operator with one value, or the reverse
)

// Codes for content (SMS and email templates).
const (
	UnknownVariable   = "unknown_variable"   // {{name}} outside the allowlist
	MalformedTemplate = "malformed_template" // broken braces, filters, nesting
	URLNotAllowed     = "url_not_allowed"    // links come only from {{campaign_url}}
	EmailNotAllowed   = "email_not_allowed"  // no email addresses in copy
	HTMLNotAllowed    = "html_not_allowed"   // copy is plain text
	RenderedTooLong   = "rendered_too_long"  // worst-case rendered text over the limit
)

// Warning codes. Warnings never block approval.
const (
	SMSMultiSegment = "sms_multi_segment" // the SMS may need more than one segment
)

// Issue is one problem. Path is a JSON Pointer into the validated document
// ("" is the document itself).
type Issue struct {
	Path    string `json:"path"`
	Code    string `json:"code"`
	Message string `json:"message"`
}

// Result collects every problem found, not just the first.
type Result struct {
	Errors   []Issue `json:"errors"`
	Warnings []Issue `json:"warnings"`
}

// OK reports whether there are no errors. Warnings do not count.
func (r Result) OK() bool { return len(r.Errors) == 0 }

// Error records an error.
func (r *Result) Error(path, code, message string) {
	r.Errors = append(r.Errors, Issue{Path: path, Code: code, Message: message})
}

// Warn records a warning.
func (r *Result) Warn(path, code, message string) {
	r.Warnings = append(r.Warnings, Issue{Path: path, Code: code, Message: message})
}
package schema

import (
	"cmp"
	"errors"
	"fmt"
	"slices"
	"strings"

	"github.com/santhosh-tekuri/jsonschema/v6"
	"github.com/santhosh-tekuri/jsonschema/v6/kind"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Issues turns an error from Validate or ValidateDef into stable issues,
// sorted by path. base is prepended to every path, so a check of one
// condition can report /conditions/2/... paths.
func Issues(err error, base string) []validation.Issue {
	var ve *jsonschema.ValidationError
	if !errors.As(err, &ve) {
		return []validation.Issue{{Path: base, Code: validation.SchemaViolation, Message: err.Error()}}
	}
	var out []validation.Issue
	collect(ve, base, &out)
	slices.SortFunc(out, func(a, b validation.Issue) int {
		return cmp.Or(cmp.Compare(a.Path, b.Path), cmp.Compare(a.Code, b.Code), cmp.Compare(a.Message, b.Message))
	})
	return slices.Compact(out)
}

// collect walks to the leaf errors; inner nodes only group their causes.
func collect(e *jsonschema.ValidationError, base string, out *[]validation.Issue) {
	if len(e.Causes) > 0 {
		for _, c := range e.Causes {
			collect(c, base, out)
		}
		return
	}
	path := base + Pointer(e.InstanceLocation)
	add := func(p, code, msg string) {
		*out = append(*out, validation.Issue{Path: p, Code: code, Message: msg})
	}
	switch k := e.ErrorKind.(type) {
	case *kind.Required:
		for _, m := range k.Missing {
			add(path+"/"+escape(m), validation.Required, fmt.Sprintf("missing required key %q", m))
		}
	case *kind.AdditionalProperties:
		for _, p := range k.Properties {
			add(path+"/"+escape(p), validation.UnknownProperty, fmt.Sprintf("key %q is not allowed", p))
		}
	case *kind.Type:
		add(path, validation.InvalidType, fmt.Sprintf("expected %s, got %s", strings.Join(k.Want, " or "), k.Got))
	case *kind.Enum:
		want := make([]string, len(k.Want))
		for i, w := range k.Want {
			want[i] = show(w)
		}
		add(path, validation.UnknownValue, fmt.Sprintf("%s is not allowed; use one of: %s", show(k.Got), strings.Join(want, ", ")))
	case *kind.Const:
		add(path, validation.UnknownValue, fmt.Sprintf("%s is not allowed; must be %s", show(k.Got), show(k.Want)))
	case *kind.Minimum:
		add(path, validation.OutOfRange, fmt.Sprintf("must be at least %s", k.Want.RatString()))
	case *kind.ExclusiveMinimum:
		add(path, validation.OutOfRange, fmt.Sprintf("must be greater than %s", k.Want.RatString()))
	case *kind.Maximum:
		add(path, validation.OutOfRange, fmt.Sprintf("must be at most %s", k.Want.RatString()))
	case *kind.ExclusiveMaximum:
		add(path, validation.OutOfRange, fmt.Sprintf("must be less than %s", k.Want.RatString()))
	case *kind.MinItems:
		add(path, validation.TooFew, fmt.Sprintf("needs at least %d items, has %d", k.Want, k.Got))
	case *kind.MaxItems:
		add(path, validation.TooMany, fmt.Sprintf("allows at most %d items, has %d", k.Want, k.Got))
	case *kind.UniqueItems:
		add(path, validation.DuplicateValue, fmt.Sprintf("items %d and %d are the same", k.Duplicates[0], k.Duplicates[1]))
	case *kind.MinLength:
		add(path, validation.TooShort, fmt.Sprintf("must be at least %d characters, has %d", k.Want, k.Got))
	case *kind.MaxLength:
		add(path, validation.TooLong, fmt.Sprintf("must be at most %d characters, has %d", k.Want, k.Got))
	default:
		add(path, validation.SchemaViolation, e.Error())
	}
}

// Pointer renders an instance location as a JSON Pointer ("" for the root).
func Pointer(loc []string) string {
	var b strings.Builder
	for _, tok := range loc {
		b.WriteString("/")
		b.WriteString(escape(tok))
	}
	return b.String()
}

func escape(tok string) string {
	return strings.ReplaceAll(strings.ReplaceAll(tok, "~", "~0"), "/", "~1")
}

func show(v any) string {
	if s, ok := v.(string); ok {
		return fmt.Sprintf("%q", s)
	}
	return fmt.Sprint(v)
}
// Package schema loads the embedded JSON Schemas (schemas/), validates
// instances against them, and derives the reduced schema that is sent to
// Claude's structured outputs.
//
// Two schemas, one source: structured outputs reject keywords such as
// maxLength and minimum, so ForAPI strips them, and Validate enforces the full
// schema locally on every response and every human edit.
package schema

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"strings"

	"github.com/santhosh-tekuri/jsonschema/v6"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/schemas"
)

// BaseURL is the $id prefix of every embedded schema. Nothing is fetched from
// it; all schemas are registered from the embedded files.
const BaseURL = "https://schemas.composer.local/"

// Name identifies an embedded schema file.
type Name string

const (
	SegmentRule Name = "segment_rule.schema.json"
	Content     Name = "content.schema.json"
	Revision    Name = "revision.schema.json"
)

// Set holds the embedded schemas, raw and compiled. Every entry under $defs
// is compiled too, so a validator can check one part of a document against
// the exact branch it belongs to and report precise errors.
type Set struct {
	raw      map[Name]any
	compiled map[Name]*jsonschema.Schema
	defs     map[string]*jsonschema.Schema // key: name + "#/$defs/" + def
}

// Load reads and compiles every embedded schema. A file whose $id does not
// match its file name is an error, so one schema cannot shadow another.
func Load() (*Set, error) {
	files, err := fs.Glob(schemas.FS, "*.schema.json")
	if err != nil {
		return nil, err
	}
	c := jsonschema.NewCompiler()
	set := &Set{raw: map[Name]any{}, compiled: map[Name]*jsonschema.Schema{}, defs: map[string]*jsonschema.Schema{}}
	for _, f := range files {
		b, err := schemas.FS.ReadFile(f)
		if err != nil {
			return nil, err
		}
		doc, err := Decode(bytes.NewReader(b))
		if err != nil {
			return nil, fmt.Errorf("schema %s: %w", f, err)
		}
		m, ok := doc.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("schema %s: not a JSON object", f)
		}
		if id, _ := m["$id"].(string); id != BaseURL+f {
			return nil, fmt.Errorf("schema %s: $id is %q, want %q", f, id, BaseURL+f)
		}
		if err := c.AddResource(BaseURL+f, doc); err != nil {
			return nil, fmt.Errorf("schema %s: %w", f, err)
		}
		set.raw[Name(f)] = doc
	}
	for name := range set.raw {
		s, err := c.Compile(BaseURL + string(name))
		if err != nil {
			return nil, fmt.Errorf("schema %s: %w", name, err)
		}
		set.compiled[name] = s
