package segment

import (
	"bytes"
	"cmp"
	"encoding/json"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Condition kinds.
const (
	KindEnum   = "enum_attribute"
	KindNumber = "number_attribute"
	KindEvent  = "event"
)

// Rule is a validated segment rule.
type Rule struct {
	Match      string // "all" or "any"
	Conditions []Condition
}

// Condition is one validated condition. Which fields are set depends on Kind.
type Condition struct {
	Kind string

	// Attribute conditions (KindEnum, KindNumber).
	Field  string
	Op     string
	Value  string   // KindEnum with eq or neq
	Values []string // KindEnum with in or not_in
	Number int      // KindNumber

	// Event conditions (KindEvent).
	Event      string
	WithinDays int
	Negate     bool
}

// ValidateJSON parses and validates a rule given as raw JSON.
func ValidateJSON(set *schema.Set, data []byte) (Rule, validation.Result) {
	doc, err := schema.Decode(bytes.NewReader(data))
	if err != nil {
		var res validation.Result
		res.Error("", validation.InvalidJSON, err.Error())
		return Rule{}, res
	}
	return Validate(set, doc)
}

// Validate checks a decoded rule (from schema.Decode) and reports every
// problem with a precise path. It first lowercases ASCII letters in enum
// strings (docs/segment-rules.md, Normalization), changing doc in place.
func Validate(set *schema.Set, doc any) (Rule, validation.Result) {
	var res validation.Result
	normalize(doc)
	err := set.Validate(schema.SegmentRule, doc)
	if err == nil {
		return toRule(doc), res
	}

	// The condition union reports a failure for each of its branches, which
	// is noise. Keep errors outside the conditions as they are, and explain
	// each failing condition against the one branch it was meant to be.
	failing := map[int]bool{}
	for _, is := range schema.Issues(err, "") {
		if i, ok := conditionIndex(is.Path); ok {
			failing[i] = true
			continue
		}
		res.Errors = append(res.Errors, is)
	}
	m, _ := doc.(map[string]any)
	conds, _ := m["conditions"].([]any)
package content

import (
	"bytes"
	"cmp"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// Rendered length limits (runes, worst case). They match the maxLength of the
// raw templates in schemas/content.schema.json; content_test.go checks that.
const (
	SMSMaxChars     = 160
	SubjectMaxChars = 80
)

// Content is validated copy.
type Content struct {
	SMSBody      string
	EmailSubject string
	EmailBody    string
	// SMS is the pessimistic estimate: longest variable values, and Turkish
	// letters in names and city.
	SMS SMSInfo
}

// Banned patterns. They are checked on the text with every variable filled
// in by a placeholder, so "{{city}}.com" is caught too. {{campaign_url}} is
// the one allowed link and is filled with a space.
var (
	schemeRe = regexp.MustCompile(`(?i)[a-z][a-z0-9+.\-]*://|www\.`)
	// A bare domain: dot-separated labels ending in a common TLD. Labels are
	// Unicode-aware, so a Cyrillic lookalike such as "іnsider.com" is caught.
	domainRe = regexp.MustCompile(`(?i)(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+` +
		`(?:com|net|org|info|biz|io|co|ai|app|dev|me|ly|gl|to|cc|tv|xyz|link|shop|store|site|online|tr|eu|uk|de|us))(?:$|[^\p{L}\p{N}_-])`)
	// A domain with any TLD, given away by the path that follows it, such as
	// "evil.top/login". The TLD starts with a letter, so "10.30/11" passes.
	domainPathRe = regexp.MustCompile(`(?:^|[^\p{L}\p{N}@._-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+\p{L}[\p{L}\p{N}-]+/)`)
	// What may touch {{campaign_url}}. Anything else could extend the link
	// into another one: "{{campaign_url}}@evil.top", "{{campaign_url}}.evil.com".
	// Before it: the start or white space, then opening punctuation.
	// After it: closing punctuation, then white space or the end.
	urlBeforeRe = regexp.MustCompile(`(?:^|[\s\p{Z}])[(\["'“‘«:]*$`)
	urlAfterRe  = regexp.MustCompile(`^[.,!?;:)\]"'”’»]*(?:[\s\p{Z}]|$)`)
	ipRe        = regexp.MustCompile(`(?:^|[^\p{N}.])(\d{1,3}(?:\.\d{1,3}){3})(?:$|[^\p{N}.])`)
	emailRe     = regexp.MustCompile(`[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+`)
	htmlRe      = regexp.MustCompile(`<\s*/?\s*[A-Za-z][^>]*>`)
)

// ValidateJSON parses and validates content given as raw JSON.
func ValidateJSON(set *schema.Set, data []byte) (Content, validation.Result) {
	doc, err := schema.Decode(bytes.NewReader(data))
	if err != nil {
		var res validation.Result
		res.Error("", validation.InvalidJSON, err.Error())
		return Content{}, res
	}
	return Validate(set, doc)
}

// Validate checks decoded content (from schema.Decode): the schema first,
// then templates, banned links, emails and HTML, and the worst-case rendered
// length. Every problem is reported. SMS encoding and segment count are
// warnings only.
func Validate(set *schema.Set, doc any) (Content, validation.Result) {
	var res validation.Result
	rawTooLong := map[string]bool{}
	if err := set.Validate(schema.Content, doc); err != nil {
		for _, is := range schema.Issues(err, "") {
			res.Errors = append(res.Errors, is)
			if is.Code == validation.TooLong {
				rawTooLong[is.Path] = true
			}
		}
	}
}

// Query is a SQL statement with its arguments.
type Query struct {
	SQL  string
	Args []any
}

// AudienceQuery selects the ids of a rule's recipients on one channel: users
// who match the rule and consented to that channel. The consent filter is
// always part of the query; a rule cannot express or remove it.
func AudienceQuery(r Rule, channel string, asOf time.Time) (Query, error) {
	consent, ok := consentColumns[channel]
	if !ok {
		return Query{}, fmt.Errorf("segment: unknown channel %q", channel)
	}
	f, err := compile(r, asOf)
	if err != nil {
		return Query{}, err
	}
	return Query{SQL: "SELECT u.id FROM users u WHERE " + f.sql + " AND " + consent, Args: f.args}, nil
}

// Counts is the audience size of a rule. Total ignores consent; the eligible
// counts are what would actually be sent per channel.
type Counts struct {
	Total         int `json:"total"`
	SMSEligible   int `json:"sms_eligible"`
	EmailEligible int `json:"email_eligible"`
}

// Querier runs one query. *pgxpool.Pool, *pgx.Conn and pgx.Tx satisfy it.
type Querier interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// CountAudience counts the users a rule matches, in total and per channel
// with consent applied.
func CountAudience(ctx context.Context, q Querier, r Rule, asOf time.Time) (Counts, error) {
	f, err := compile(r, asOf)
	if err != nil {
		return Counts{}, err
	}
	sql := "SELECT count(*), count(*) FILTER (WHERE " + consentColumns["sms"] + "), count(*) FILTER (WHERE " +
		consentColumns["email"] + ") FROM users u WHERE " + f.sql
	var c Counts
	if err := q.QueryRow(ctx, sql, f.args...).Scan(&c.Total, &c.SMSEligible, &c.EmailEligible); err != nil {
		return Counts{}, fmt.Errorf("segment: count: %w", err)
	}
	return c, nil
}
// Package testdb gives integration tests their own Postgres database, so
// packages can run in parallel without touching each other's data.
//
// Tests need TEST_DATABASE_URL (an admin connection to the test server).
// Without it they skip, unless REQUIRE_DB=1, which make test sets: then a
// missing database fails the run instead of silently skipping it.
package testdb

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"net/url"
	"os"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
)

// cloneLock serializes template clones across test packages: Postgres
// refuses to copy a template database while another session uses it.
const cloneLock int64 = 0x7e57db

// Fresh creates an empty database for the calling test, drops it when the
// test ends, and returns its connection URL.
func Fresh(t testing.TB) string {
	t.Helper()
	return create(t, "")
}

// Seed describes the data in a seeded clone, read from its seed_meta row.
type Seed struct {
	AsOf  time.Time
	Seed  int64
	Users int
}

// Seeded clones the template database that make test builds (migrated, then
// seeded at a fixed anchor) for the calling test, drops the clone when the
// test ends, and returns its URL and seed parameters. The template name is
// TEST_TEMPLATE_DB, default app_template.
func Seeded(t testing.TB) (string, Seed) {
	t.Helper()
	template := os.Getenv("TEST_TEMPLATE_DB")
	if template == "" {
		template = "app_template"
	}
	u := create(t, template)

	db, err := sql.Open("pgx", u)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var s Seed
	if err := db.QueryRow("SELECT as_of, seed, user_count FROM seed_meta").Scan(&s.AsOf, &s.Seed, &s.Users); err != nil {
		t.Fatalf("template %s has no seed_meta row (build it with make test): %v", template, err)
	}
	s.AsOf = s.AsOf.UTC()
	return u, s
}

func create(t testing.TB, template string) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		if os.Getenv("REQUIRE_DB") == "1" {
			t.Fatal("REQUIRE_DB=1 but TEST_DATABASE_URL is not set")
		}
		t.Skip("TEST_DATABASE_URL is not set; run the integration tests with make test")
	}
	admin, err := sql.Open("pgx", base)
	if err != nil {
		t.Fatal(err)
	}
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	name := "test_" + hex.EncodeToString(b)

	ctx := context.Background()
	conn, err := admin.Conn(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stmt := "CREATE DATABASE " + name
	if template != "" {
		stmt += " TEMPLATE " + pgx.Identifier{template}.Sanitize()
		if _, err := conn.ExecContext(ctx, "SELECT pg_advisory_lock($1)", cloneLock); err != nil {
			t.Fatal(err)
		}
	}
	_, createErr := conn.ExecContext(ctx, stmt)
	if template != "" {
		_, _ = conn.ExecContext(ctx, "SELECT pg_advisory_unlock($1)", cloneLock)
	}
	conn.Close()
	if createErr != nil {
		t.Fatalf("%s: %v (the template is built by make test)", stmt, createErr)
	}

	t.Cleanup(func() {
		if _, err := admin.Exec("DROP DATABASE " + name + " WITH (FORCE)"); err != nil {
			t.Errorf("drop %s: %v", name, err)
		}
		admin.Close()
	})
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	u.Path = "/" + name
	return u.String()
}
package httpapi

import (
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"regexp"
	"slices"
	"strings"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
)

const token = "test-token"

func handler(t *testing.T, s *Server) http.Handler {
	t.Helper()
	if s.Schemas == nil {
		set, err := schema.Load()
		if err != nil {
			t.Fatal(err)
		}
		s.Schemas = set
	}
	h, err := s.Handler()
	if err != nil {
		t.Fatal(err)
	}
	return h
