// Query is a SQL statement with its arguments.
type Query struct {
	SQL  string
	Args []any
}

// AudienceQuery selects the ids of a rule's recipients on one channel: users
// who match the rule and consented to that channel. The consent filter is
// always part of the query; a rule cannot express or remove it.
func AudienceQuery(r Rule, channel string, asOf time.Time) (Query, error) {
	consent, ok := consentColumns[channel]
	if !ok {
		return Query{}, fmt.Errorf("segment: unknown channel %q", channel)
	}
	f, err := compile(r, asOf)
	if err != nil {
		return Query{}, err
	}
	return Query{SQL: "SELECT u.id FROM users u WHERE " + f.sql + " AND " + consent, Args: f.args}, nil
}

// Counts is the audience size of a rule. Total ignores consent; the eligible
// counts are what would actually be sent per channel.
type Counts struct {
	Total         int `json:"total"`
	SMSEligible   int `json:"sms_eligible"`
	EmailEligible int `json:"email_eligible"`
}

// Querier runs one query. *pgxpool.Pool, *pgx.Conn and pgx.Tx satisfy it.
type Querier interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// CountAudience counts the users a rule matches, in total and per channel
// with consent applied.
func CountAudience(ctx context.Context, q Querier, r Rule, asOf time.Time) (Counts, error) {
	f, err := compile(r, asOf)
	if err != nil {
		return Counts{}, err
	}
	sql := "SELECT count(*), count(*) FILTER (WHERE " + consentColumns["sms"] + "), count(*) FILTER (WHERE " +
		consentColumns["email"] + ") FROM users u WHERE " + f.sql
	var c Counts
	if err := q.QueryRow(ctx, sql, f.args...).Scan(&c.Total, &c.SMSEligible, &c.EmailEligible); err != nil {
		return Counts{}, fmt.Errorf("segment: count: %w", err)
	}
	return c, nil
}
// Package testdb gives integration tests their own Postgres database, so
// packages can run in parallel without touching each other's data.
//
// Tests need TEST_DATABASE_URL (an admin connection to the test server).
// Without it they skip, unless REQUIRE_DB=1, which make test sets: then a
// missing database fails the run instead of silently skipping it.
package testdb

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"net/url"
	"os"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
)

// cloneLock serializes template clones across test packages: Postgres
// refuses to copy a template database while another session uses it.
const cloneLock int64 = 0x7e57db

// Fresh creates an empty database for the calling test, drops it when the
// test ends, and returns its connection URL.
func Fresh(t testing.TB) string {
	t.Helper()
	return create(t, "")
}

// Seed describes the data in a seeded clone, read from its seed_meta row.
type Seed struct {
	AsOf  time.Time
	Seed  int64
	Users int
}

// Seeded clones the template database that make test builds (migrated, then
// seeded at a fixed anchor) for the calling test, drops the clone when the
// test ends, and returns its URL and seed parameters. The template name is
// TEST_TEMPLATE_DB, default app_template.
func Seeded(t testing.TB) (string, Seed) {
	t.Helper()
	template := os.Getenv("TEST_TEMPLATE_DB")
	if template == "" {
		template = "app_template"
	}
	u := create(t, template)

	db, err := sql.Open("pgx", u)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var s Seed
	if err := db.QueryRow("SELECT as_of, seed, user_count FROM seed_meta").Scan(&s.AsOf, &s.Seed, &s.Users); err != nil {
		t.Fatalf("template %s has no seed_meta row (build it with make test): %v", template, err)
	}
	s.AsOf = s.AsOf.UTC()
	return u, s
}

func create(t testing.TB, template string) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		if os.Getenv("REQUIRE_DB") == "1" {
			t.Fatal("REQUIRE_DB=1 but TEST_DATABASE_URL is not set")
		}
		t.Skip("TEST_DATABASE_URL is not set; run the integration tests with make test")
	}
	admin, err := sql.Open("pgx", base)
	if err != nil {
		t.Fatal(err)
	}
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	name := "test_" + hex.EncodeToString(b)

	ctx := context.Background()
	conn, err := admin.Conn(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stmt := "CREATE DATABASE " + name
	if template != "" {
		stmt += " TEMPLATE " + pgx.Identifier{template}.Sanitize()
		if _, err := conn.ExecContext(ctx, "SELECT pg_advisory_lock($1)", cloneLock); err != nil {
			t.Fatal(err)
		}
	}
	_, createErr := conn.ExecContext(ctx, stmt)
	if template != "" {
		_, _ = conn.ExecContext(ctx, "SELECT pg_advisory_unlock($1)", cloneLock)
	}
	conn.Close()
	if createErr != nil {
		t.Fatalf("%s: %v (the template is built by make test)", stmt, createErr)
	}

	t.Cleanup(func() {
		if _, err := admin.Exec("DROP DATABASE " + name + " WITH (FORCE)"); err != nil {
			t.Errorf("drop %s: %v", name, err)
		}
		admin.Close()
	})
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	u.Path = "/" + name
	return u.String()
}
