  }
  type SendWorker struct {
      river.WorkerDefaults[jobs.SendArgs]
      DB              DB
      ProviderURL     string             // POST {ProviderURL}/v1/messages
      Client          *http.Client       // optional
      Limiters        map[string]Limiter // by channel; one Wait per provider call
      ProviderTimeout time.Duration      // 0 means ProviderTimeout
      Now             func() time.Time   // every time decision: first_attempt_at, next_attempt_at, age
      Backoff         func(retry int) time.Duration // retry 0 is the first retry; default retry.Backoff
      Log             *slog.Logger
  }
  func (w *SendWorker) Work(ctx context.Context, job *river.Job[jobs.SendArgs]) error
