29	func schemas(t *testing.T) *schema.Set {
30		t.Helper()
31		set, err := schema.Load()
32		if err != nil {
33			t.Fatal(err)
34		}
35		return set
36	}
37	
38	func serve(t *testing.T, o mockllm.Options) (*mockllm.Server, *httptest.Server) {
39		t.Helper()
40		m := mockllm.New(o)
41		srv := httptest.NewServer(m)
42		t.Cleanup(srv.Close)
43		return m, srv
44	}
45	
46	// body builds a request the way internal/llm sends it: the API-derived
47	// schema of the stage, adaptive thinking, explicit effort, no sampling
48	// parameters.
49	func body(t *testing.T, stage mockllm.Stage, stream bool, userTurns ...string) map[string]any {
50		t.Helper()
51		name, effort := schema.SegmentRule, "low"
52		if stage == mockllm.Content {
53			name, effort = schema.Content, "medium"
54		}
55		s, err := schemas(t).ForAPI(name)
56		if err != nil {
57			t.Fatal(err)
58		}
59		var msgs []any
60		for i, u := range userTurns {
61			if i > 0 {
62				msgs = append(msgs, map[string]any{"role": "assistant", "content": []any{
63					map[string]any{"type": "thinking", "thinking": "", "signature": "sig"},
64					map[string]any{"type": "text", "text": `{"broken":true}`},
65				}})
66			}
67			msgs = append(msgs, map[string]any{"role": "user", "content": u})
68		}
69		return roundTrip(t, map[string]any{
70			"model":         "claude-opus-5-5",
71			"max_tokens":    4096,
72			"stream":        stream,
73			"system":        "system prompt",
74			"thinking":      map[string]any{"type": "adaptive"},
75			"output_config": map[string]any{"effort": effort, "format": map[string]any{"type": "json_schema", "schema": s}},
76			"fallbacks":     "default",
77			"messages":      msgs,
78		})
79	}
