81	// roundTrip turns any JSON value into plain maps, so tests can mutate it.
82	func roundTrip(t *testing.T, v any) map[string]any {
83		t.Helper()
84		b, err := json.Marshal(v)
85		if err != nil {
86			t.Fatal(err)
87		}
88		var out map[string]any
89		if err := json.Unmarshal(b, &out); err != nil {
90			t.Fatal(err)
91		}
92		return out
93	}
94	
95	var apiHeaders = map[string]string{"x-api-key": "mock-placeholder", "anthropic-version": "2023-06-01", "content-type": "application/json"}
96	
97	func post(t *testing.T, srv *httptest.Server, b map[string]any, headers map[string]string) *http.Response {
98		t.Helper()
99		raw, err := json.Marshal(b)
100		if err != nil {
101			t.Fatal(err)
102		}
103		req, err := http.NewRequest("POST", srv.URL+"/v1/messages", bytes.NewReader(raw))
104		if err != nil {
105			t.Fatal(err)
106		}
107		for k, v := range headers {
108			req.Header.Set(k, v)
109		}
110		resp, err := srv.Client().Do(req)
111		if err != nil {
112			t.Fatal(err)
113		}
114		t.Cleanup(func() { resp.Body.Close() })
115		return resp
116	}
117	
118	type sse struct {
119		Event string
120		Data  map[string]any
121	}
122	
123	func readSSE(t *testing.T, r io.Reader) []sse {
124		t.Helper()
125		var out []sse
126		var cur sse
127		sc := bufio.NewScanner(r)
128		for sc.Scan() {
129			line := sc.Text()
130			switch {
131			case line == "":
132				if cur.Event != "" || cur.Data != nil {
133					out = append(out, cur)
134				}
135				cur = sse{}
136			case strings.HasPrefix(line, "event: "):
137				cur.Event = strings.TrimPrefix(line, "event: ")
138			case strings.HasPrefix(line, "data: "):
139				if err := json.Unmarshal([]byte(strings.TrimPrefix(line, "data: ")), &cur.Data); err != nil {
140					t.Fatalf("data is not JSON: %q", line)
141				}
142			}
143		}
144		return out
145	}
146	
147	// text concatenates the text deltas of a stream.
148	func text(events []sse) (string, int) {
149		var sb strings.Builder
150		n := 0
151		for _, e := range events {
152			d, _ := e.Data["delta"].(map[string]any)
153			if e.Event == "content_block_delta" && d["type"] == "text_delta" {
154				s, _ := d["text"].(string)
155				sb.WriteString(s)
156				n++
157			}
158		}
159		return sb.String(), n
160	}
161	
162	// TestStreamEventSequence pins the SSE sequence of the real API, so the SDK
163	// accumulates our mock's answers exactly as it would Claude's.
164	func TestStreamEventSequence(t *testing.T) {
165		m, srv := serve(t, mockllm.Options{})
166		answer := `{"sms":{"body":"` + strings.Repeat("Merhaba {{first_name}} ", 8) + `"},"email":{"subject":"Sepet","body":"Selam"}}`
167		m.Script(mockllm.Content, mockllm.Reply{Text: answer})
168		resp := post(t, srv, body(t, mockllm.Content, true, "<brief>b</brief>"), apiHeaders)
169		if resp.StatusCode != 200 || !strings.HasPrefix(resp.Header.Get("Content-Type"), "text/event-stream") {
170			t.Fatalf("status %d, content type %q", resp.StatusCode, resp.Header.Get("Content-Type"))
171		}
172		events := readSSE(t, resp.Body)
173		var names []string
174		for _, e := range events {
175			names = append(names, e.Event)
176			if e.Data["type"] != e.Event {
177				t.Errorf("event %q carries data of type %v", e.Event, e.Data["type"])
178			}
179		}
180		if len(names) < 8 || names[0] != "message_start" || names[len(names)-2] != "message_delta" || names[len(names)-1] != "message_stop" {
181			t.Fatalf("event names %v", names)
182		}
183		msg, _ := events[0].Data["message"].(map[string]any)
184		if usage, _ := msg["usage"].(map[string]any); usage["input_tokens"] == nil || usage["input_tokens"].(float64) <= 0 {
185			t.Errorf("message_start usage %v", msg["usage"])
186		}
187		// Blocks: index 0 is an empty thinking block, index 1 the text.
188		var starts []map[string]any
189		for _, e := range events {
190			if e.Event == "content_block_start" {
191				cb, _ := e.Data["content_block"].(map[string]any)
192				cb["index"] = e.Data["index"]
193				starts = append(starts, cb)
194			}
195		}
196		if len(starts) != 2 || starts[0]["type"] != "thinking" || starts[0]["thinking"] != "" || starts[0]["index"] != 0.0 ||
197			starts[1]["type"] != "text" || starts[1]["index"] != 1.0 {
198			t.Errorf("content blocks %v; want an empty thinking block, then a text block", starts)
199		}
200		got, n := text(events)
201		if got != answer {
202			t.Errorf("text deltas rebuild %q, want %q", got, answer)
203		}
204		if n < 2 {
205			t.Errorf("%d text deltas; the answer must arrive in chunks so streaming is exercised", n)
206		}
207		md := events[len(events)-2].Data
208		d, _ := md["delta"].(map[string]any)
209		u, _ := md["usage"].(map[string]any)
210		if d["stop_reason"] != "end_turn" || u["output_tokens"] == nil || u["output_tokens"].(float64) <= 0 {
211			t.Errorf("message_delta %v", md)
212		}
213	}
