215	func TestNonStreamedReply(t *testing.T) {
216		m, srv := serve(t, mockllm.Options{})
217		m.Script(mockllm.Segment, mockllm.Reply{Text: `{"x":1}`})
218		resp := post(t, srv, body(t, mockllm.Segment, false, "<brief>b</brief>"), apiHeaders)
219		var msg struct {
220			Type       string           `json:"type"`
221			Role       string           `json:"role"`
222			Model      string           `json:"model"`
223			Content    []map[string]any `json:"content"`
224			StopReason string           `json:"stop_reason"`
225			Usage      struct {
226				InputTokens  int `json:"input_tokens"`
227				OutputTokens int `json:"output_tokens"`
228			} `json:"usage"`
229		}
230		if err := json.NewDecoder(resp.Body).Decode(&msg); err != nil || resp.StatusCode != 200 {
231			t.Fatalf("status %d, decode %v", resp.StatusCode, err)
232		}
233		if msg.Type != "message" || msg.Role != "assistant" || msg.Model != "claude-opus-5-5" || msg.StopReason != "end_turn" ||
234			msg.Usage.InputTokens <= 0 || msg.Usage.OutputTokens <= 0 {
