242	func apiErrorType(t *testing.T, resp *http.Response) string {
243		t.Helper()
244		var e struct {
245			Type  string `json:"type"`
246			Error struct {
247				Type    string `json:"type"`
248				Message string `json:"message"`
249			} `json:"error"`
250		}
251		if err := json.NewDecoder(resp.Body).Decode(&e); err != nil {
252			t.Fatalf("not an API error body: %v", err)
253		}
254		if e.Type != "error" || e.Error.Message == "" {
255			t.Errorf("error body %+v", e)
256		}
257		return e.Error.Type
258	}
