268	// TestRejectsWhatTheAPIRejects makes drift in our requests fail in tests,
269	// not in production: each case is a shape the real API answers with a 400.
270	func TestRejectsWhatTheAPIRejects(t *testing.T) {
271		_, srv := serve(t, mockllm.Options{})
272		contentSchema := func(b map[string]any) map[string]any { return at(b, "output_config", "format", "schema") }
273		smsBody := func(b map[string]any) map[string]any {
274			return at(contentSchema(b), "properties", "sms", "properties", "body")
275		}
276		cases := []struct {
277			name   string
278			mutate func(b map[string]any)
279		}{
280			{"temperature", func(b map[string]any) { b["temperature"] = 0.2 }},
281			{"top_p", func(b map[string]any) { b["top_p"] = 0.9 }},
282			{"top_k", func(b map[string]any) { b["top_k"] = 5 }},
283			{"forced tool_choice any", func(b map[string]any) {
284				b["tools"] = []any{map[string]any{"name": "emit", "input_schema": map[string]any{"type": "object"}}}
285				b["tool_choice"] = map[string]any{"type": "any"}
286			}},
287			{"forced tool_choice tool", func(b map[string]any) {
288				b["tools"] = []any{map[string]any{"name": "emit", "input_schema": map[string]any{"type": "object"}}}
289				b["tool_choice"] = map[string]any{"type": "tool", "name": "emit"}
290			}},
291			{"thinking disabled", func(b map[string]any) { b["thinking"] = map[string]any{"type": "disabled"} }},
292			{"thinking budget", func(b map[string]any) { b["thinking"] = map[string]any{"type": "enabled", "budget_tokens": 2048} }},
293			{"minLength", func(b map[string]any) { smsBody(b)["minLength"] = 1 }},
294			{"maxLength", func(b map[string]any) { smsBody(b)["maxLength"] = 160 }},
295			{"minimum", func(b map[string]any) { smsBody(b)["type"] = "integer"; smsBody(b)["minimum"] = 0 }},
296			{"maximum", func(b map[string]any) { smsBody(b)["type"] = "integer"; smsBody(b)["maximum"] = 9 }},
297			{"minItems above 1", func(b map[string]any) {
298				at(contentSchema(b), "properties")["tags"] = map[string]any{"type": "array", "items": map[string]any{"type": "string"}, "minItems": 2}
299			}},
300			{"external $ref", func(b map[string]any) {
301				at(contentSchema(b), "properties")["sms"] = map[string]any{"$ref": "https://schemas.example/other.json#/x"}
302			}},
303			{"additionalProperties true", func(b map[string]any) { contentSchema(b)["additionalProperties"] = true }},
304			{"additionalProperties as a schema", func(b map[string]any) {
305				at(contentSchema(b), "properties", "sms")["additionalProperties"] = map[string]any{"type": "string"}
306			}},
307			{"object without additionalProperties", func(b map[string]any) { delete(at(contentSchema(b), "properties", "email"), "additionalProperties") }},
308		}
309		for _, c := range cases {
310			b := body(t, mockllm.Content, true, "<brief>b</brief>")
311			c.mutate(b)
312			resp := post(t, srv, b, apiHeaders)
313			if resp.StatusCode != http.StatusBadRequest {
314				t.Errorf("%s: status %d, want 400", c.name, resp.StatusCode)
315				continue
316			}
317			if typ := apiErrorType(t, resp); typ != "invalid_request_error" {
318				t.Errorf("%s: error type %q, want invalid_request_error", c.name, typ)
319			}
320		}
321	
322		// What internal/llm sends must pass, for both stages.
323		for _, stage := range []mockllm.Stage{mockllm.Segment, mockllm.Content} {
324			if resp := post(t, srv, body(t, stage, true, "<brief>"+turkishBrief+"</brief>"), apiHeaders); resp.StatusCode != 200 {
325				t.Errorf("valid %s request: status %d", stage, resp.StatusCode)
326			}
327		}
328	
329		noKey := map[string]string{"anthropic-version": "2023-06-01", "content-type": "application/json"}
330		if resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>b</brief>"), noKey); resp.StatusCode != http.StatusUnauthorized || apiErrorType(t, resp) != "authentication_error" {
331			t.Errorf("no x-api-key: status %d, want 401 authentication_error", resp.StatusCode)
332		}
333		noVersion := map[string]string{"x-api-key": "mock-placeholder", "content-type": "application/json"}
334		if resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>b</brief>"), noVersion); resp.StatusCode != http.StatusBadRequest {
335			t.Errorf("no anthropic-version: status %d, want 400", resp.StatusCode)
336		}
337	}
338	
339	// Scripted failures come back in the API's error format, with the headers
340	// the retry classifier reads.
341	func TestScriptedErrors(t *testing.T) {
342		m, srv := serve(t, mockllm.Options{})
343		m.Script(mockllm.Segment, mockllm.Status(529), mockllm.RateLimited("2"), mockllm.Status(500), mockllm.Status(400))
344		want := []struct {
345			status int
346			typ    string
347		}{{529, "overloaded_error"}, {429, "rate_limit_error"}, {500, "api_error"}, {400, "invalid_request_error"}}
348		for i, w := range want {
349			resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>"+turkishBrief+"</brief>"), apiHeaders)
350			if resp.StatusCode != w.status {
351				t.Fatalf("reply %d: status %d, want %d", i, resp.StatusCode, w.status)
352			}
353			if w.status == 429 && resp.Header.Get("Retry-After") != "2" {
354				t.Errorf("429 without Retry-After: %v", resp.Header)
355			}
356			if typ := apiErrorType(t, resp); typ != w.typ {
357				t.Errorf("reply %d: error type %q, want %q", i, typ, w.typ)
358			}
359		}
360		// The script is used up: the brain answers.
361		if resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>"+turkishBrief+"</brief>"), apiHeaders); resp.StatusCode != 200 {
362			t.Errorf("after the script: status %d, want 200", resp.StatusCode)
363		}
364	}
365	
366	func TestScriptedStopReasons(t *testing.T) {
367		m, srv := serve(t, mockllm.Options{})
368		m.Script(mockllm.Content, mockllm.Refusal(), mockllm.MaxTokens(`{"sms":{"body":"Mer`))
369		for _, want := range []struct{ stop, text string }{{"refusal", ""}, {"max_tokens", `{"sms":{"body":"Mer`}} {
370			events := readSSE(t, post(t, srv, body(t, mockllm.Content, true, "<brief>b</brief>"), apiHeaders).Body)
371			got, _ := text(events)
372			d, _ := events[len(events)-2].Data["delta"].(map[string]any)
373			if d["stop_reason"] != want.stop || got != want.text {
374				t.Errorf("stop reason %v with text %q, want %s with %q", d["stop_reason"], got, want.stop, want.text)
375			}
376		}
377	}
378	
379	// A stall sends its prefix and then nothing, until the client gives up. The
380	// handler must return then, or the server could not shut down.
381	func TestStall(t *testing.T) {
382		m, srv := serve(t, mockllm.Options{})
383		m.Script(mockllm.Content, mockllm.Stall(`{"sms":{"body":"Mer`))
384		ctx, cancel := context.WithTimeout(context.Background(), 400*time.Millisecond)
385		defer cancel()
386		raw, _ := json.Marshal(body(t, mockllm.Content, true, "<brief>b</brief>"))
387		req, _ := http.NewRequestWithContext(ctx, "POST", srv.URL+"/v1/messages", bytes.NewReader(raw))
388		for k, v := range apiHeaders {
389			req.Header.Set(k, v)
390		}
391		resp, err := srv.Client().Do(req)
392		if err != nil {
393			t.Fatal(err)
394		}
395		defer resp.Body.Close()
396		start := time.Now()
397		all, readErr := io.ReadAll(resp.Body)
398		if readErr == nil {
399			t.Fatalf("the stream ended on its own after %v: %s", time.Since(start), all)
400		}
401		if !strings.Contains(string(all), `Mer`) || strings.Contains(string(all), "message_stop") {
402			t.Errorf("stalled stream sent %q; want the prefix and no message_stop", all)
403		}
404		done := make(chan struct{})
405		go func() { srv.Close(); close(done) }()
406		select {
407		case <-done:
408		case <-time.After(3 * time.Second):
409			t.Fatal("server shutdown blocked on the stalled handler")
410		}
411	}
412	
413	// Scripts are per stage and used in order. Every request is recorded with
414	// its stage, headers and exact body.
415	func TestScriptsAndRecording(t *testing.T) {
416		m, srv := serve(t, mockllm.Options{})
417		m.Script(mockllm.Content, mockllm.Reply{Text: "A"}, mockllm.Reply{Text: "B"})
418		send := func(stage mockllm.Stage) string {
419			got, _ := text(readSSE(t, post(t, srv, body(t, stage, true, "<brief>"+turkishBrief+"</brief>"), apiHeaders).Body))
420			return got
421		}
422		seg := send(mockllm.Segment)
423		a, b, brain := send(mockllm.Content), send(mockllm.Content), send(mockllm.Content)
424		if a != "A" || b != "B" {
425			t.Errorf("content replies %q, %q; want the script in order", a, b)
426		}
427		if _, res := segment.ValidateJSON(schemas(t), []byte(seg)); !res.OK() {
428			t.Errorf("unscripted segment request: brain answer %q is invalid: %+v", seg, res.Errors)
429		}
430		if _, res := content.ValidateJSON(schemas(t), []byte(brain)); !res.OK() {
431			t.Errorf("content after the script: brain answer %q is invalid: %+v", brain, res.Errors)
432		}
433		reqs := m.Requests()
434		if len(reqs) != 4 {
435			t.Fatalf("%d recorded requests, want 4", len(reqs))
436		}
437		stages := []mockllm.Stage{mockllm.Segment, mockllm.Content, mockllm.Content, mockllm.Content}
438		for i, r := range reqs {
439			if r.Stage != stages[i] || r.Header.Get("x-api-key") != "mock-placeholder" {
440				t.Errorf("request %d: stage %q, headers %v", i, r.Stage, r.Header)
441			}
442			var b map[string]any
443			if err := json.Unmarshal(r.Body, &b); err != nil || b["model"] != "claude-opus-5-5" {
444				t.Errorf("request %d: body not recorded as sent: %v", i, err)
445			}
446		}
447	}
448	
449	func brainAnswer(t *testing.T, srv *httptest.Server, stage mockllm.Stage, userTurns ...string) string {
450		t.Helper()
451		got, _ := text(readSSE(t, post(t, srv, body(t, stage, true, userTurns...), apiHeaders).Body))
452		return got
453	}
454	
455	// The demo brain turns the spec's brief into the documented rule, so
456	// docker compose up shows the real flow without a key.
457	func TestDemoBrain(t *testing.T) {
458		set := schemas(t)
459		example, err := os.ReadFile("../../docs/examples/istanbul_cart_abandoners.json")
460		if err != nil {
461			t.Fatal(err)
462		}
463		wantExample, res := segment.ValidateJSON(set, example)
464		if !res.OK() {
465			t.Fatal(res.Errors)
466		}
467		rule := func(city string, days int) segment.Rule {
468			return segment.Rule{Match: "all", Conditions: []segment.Condition{
469				{Kind: segment.KindEnum, Field: "city", Op: "eq", Value: city},
470				{Kind: segment.KindEvent, Event: "cart_add", WithinDays: days},
471				{Kind: segment.KindEvent, Event: "purchase", WithinDays: days, Negate: true},
472			}}
473		}
474		cases := []struct {
475			brief string
476			want  segment.Rule
477		}{
478			{turkishBrief, wantExample},
479			{"Son 7 günde sepete ürün ekleyip satın almayan İzmir kullanıcılarına hatırlatma gönder.", rule("izmir", 7)},
480			{"Remind Ankara users who added items to their cart in the last 14 days but did not purchase.", rule("ankara", 14)},
481		}
482		_, srv := serve(t, mockllm.Options{})
483		for _, c := range cases {
484			seg := brainAnswer(t, srv, mockllm.Segment, "<brief>"+c.brief+"</brief>")
485			got, res := segment.ValidateJSON(set, []byte(seg))
486			if !res.OK() {
487				t.Errorf("%q: invalid rule %s: %+v", c.brief, seg, res.Errors)
488				continue
489			}
490			if !reflect.DeepEqual(got, c.want) {
491				t.Errorf("%q: rule %+v, want %+v", c.brief, got, c.want)
492			}
493			copyText := brainAnswer(t, srv, mockllm.Content, "<brief>"+c.brief+"</brief>\nSegment: "+segment.Describe(got))
494			cont, res := content.ValidateJSON(set, []byte(copyText))
495			if !res.OK() {
496				t.Errorf("%q: invalid copy %s: %+v", c.brief, copyText, res.Errors)
497				continue
498			}
499			for _, field := range []string{cont.SMSBody, cont.EmailBody} {
500				if !strings.Contains(field, "{{first_name}}") || !strings.Contains(field, "{{campaign_url}}") {
501					t.Errorf("%q: copy %q lacks {{first_name}} or {{campaign_url}}", c.brief, field)
502				}
503			}
504		}
505	}
506	
507	// MOCKLLM_INVALID_FIRST shows the repair loop in a demo: a first attempt (a
508	// conversation with one message) is invalid, a repaired one is valid.
509	func TestInvalidFirst(t *testing.T) {
510		set := schemas(t)
511		_, srv := serve(t, mockllm.Options{InvalidFirst: true})
512		brief := "<brief>" + turkishBrief + "</brief>"
513		if _, res := segment.ValidateJSON(set, []byte(brainAnswer(t, srv, mockllm.Segment, brief))); res.OK() {
514			t.Error("first segment attempt is valid; want invalid")
515		}
516		if _, res := content.ValidateJSON(set, []byte(brainAnswer(t, srv, mockllm.Content, brief))); res.OK() {
517			t.Error("first content attempt is valid; want invalid")
518		}
519		if _, res := segment.ValidateJSON(set, []byte(brainAnswer(t, srv, mockllm.Segment, brief, "fix: [...]"))); !res.OK() {
520			t.Errorf("repaired segment attempt is invalid: %+v", res.Errors)
521		}
522		if _, res := content.ValidateJSON(set, []byte(brainAnswer(t, srv, mockllm.Content, brief, "fix: [...]"))); !res.OK() {
523			t.Errorf("repaired content attempt is invalid: %+v", res.Errors)
524		}
525	
526		for env, want := range map[string]bool{"true": true, "": false, "1": false, "false": false} {
527			got := mockllm.OptionsFromEnv(func(k string) string {
528				if k == "MOCKLLM_INVALID_FIRST" {
529					return env
530				}
531				return ""
532			})
533			if got.InvalidFirst != want {
534				t.Errorf("MOCKLLM_INVALID_FIRST=%q: InvalidFirst %v, want %v", env, got.InvalidFirst, want)
535			}
536		}
537	}
538	
539	// The mock is used through the real SDK in internal/llm. This checks the SDK
540	// accumulates a mock stream into a full message and maps a mock error to its
541	// typed error.
542	func TestThroughRealSDK(t *testing.T) {
543		m, srv := serve(t, mockllm.Options{})
544		answer := `{"sms":{"body":"Merhaba {{first_name}} {{campaign_url}}"},"email":{"subject":"Sepet","body":"Selam"}}`
545		m.Script(mockllm.Content, mockllm.Reply{Text: answer}, mockllm.Status(529))
546		s, err := schemas(t).ForAPI(schema.Content)
547		if err != nil {
548			t.Fatal(err)
549		}
550		client := anthropic.NewClient(option.WithBaseURL(srv.URL), option.WithAPIKey("mock-placeholder"), option.WithMaxRetries(0))
551		params := anthropic.MessageNewParams{
552			Model:     "claude-opus-5-5",
553			MaxTokens: 4096,
554			Messages:  []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock("<brief>b</brief>"))},
555		}
556		format := option.WithJSONSet("output_config", map[string]any{"effort": "medium", "format": map[string]any{"type": "json_schema", "schema": s}})
557		ctx := context.Background()
558	
559		stream := client.Messages.NewStreaming(ctx, params, format)
560		msg := anthropic.Message{}
561		for stream.Next() {
562			if err := msg.Accumulate(stream.Current()); err != nil {
563				t.Fatal(err)
564			}
565		}
566		if err := stream.Err(); err != nil {
567			t.Fatal(err)
568		}
569		var got string
570		for _, b := range msg.Content {
571			if tb, ok := b.AsAny().(anthropic.TextBlock); ok {
572				got += tb.Text
573			}
574		}
575		if got != answer || msg.StopReason != anthropic.StopReasonEndTurn {
576			t.Errorf("accumulated %q (stop %q), want %q", got, msg.StopReason, answer)
577		}
578	
579		_, err = client.Messages.New(ctx, params, format)
580		var apiErr *anthropic.Error
581		if !errors.As(err, &apiErr) || apiErr.StatusCode != 529 {
582			t.Errorf("529 through the SDK: %v", err)
583		}
584		if n := len(m.Requests()); n != 2 {
585			t.Errorf("%d requests; the SDK retried despite WithMaxRetries(0)", n)
586		}
587	}
