284				b["tools"] = []any{map[string]any{"name": "emit", "input_schema": map[string]any{"type": "object"}}}
285				b["tool_choice"] = map[string]any{"type": "any"}
286			}},
287			{"forced tool_choice tool", func(b map[string]any) {
288				b["tools"] = []any{map[string]any{"name": "emit", "input_schema": map[string]any{"type": "object"}}}
289				b["tool_choice"] = map[string]any{"type": "tool", "name": "emit"}
290			}},
291			{"thinking disabled", func(b map[string]any) { b["thinking"] = map[string]any{"type": "disabled"} }},
292			{"thinking budget", func(b map[string]any) { b["thinking"] = map[string]any{"type": "enabled", "budget_tokens": 2048} }},
293			{"minLength", func(b map[string]any) { smsBody(b)["minLength"] = 1 }},
294			{"maxLength", func(b map[string]any) { smsBody(b)["maxLength"] = 160 }},
295			{"minimum", func(b map[string]any) { smsBody(b)["type"] = "integer"; smsBody(b)["minimum"] = 0 }},
296			{"maximum", func(b map[string]any) { smsBody(b)["type"] = "integer"; smsBody(b)["maximum"] = 9 }},
