325				t.Errorf("valid %s request: status %d", stage, resp.StatusCode)
326			}
327		}
328	
329		noKey := map[string]string{"anthropic-version": "2023-06-01", "content-type": "application/json"}
330		if resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>b</brief>"), noKey); resp.StatusCode != http.StatusUnauthorized || apiErrorType(t, resp) != "authentication_error" {
331			t.Errorf("no x-api-key: status %d, want 401 authentication_error", resp.StatusCode)
332		}
333		noVersion := map[string]string{"x-api-key": "mock-placeholder", "content-type": "application/json"}
334		if resp := post(t, srv, body(t, mockllm.Segment, true, "<brief>b</brief>"), noVersion); resp.StatusCode != http.StatusBadRequest {
335			t.Errorf("no anthropic-version: status %d, want 400", resp.StatusCode)
