379	// A stall sends its prefix and then nothing, until the client gives up. The
380	// handler must return then, or the server could not shut down.
381	func TestStall(t *testing.T) {
382		m, srv := serve(t, mockllm.Options{})
383		m.Script(mockllm.Content, mockllm.Stall(`{"sms":{"body":"Mer`))
384		ctx, cancel := context.WithTimeout(context.Background(), 400*time.Millisecond)
385		defer cancel()
386		raw, _ := json.Marshal(body(t, mockllm.Content, true, "<brief>b</brief>"))
387		req, _ := http.NewRequestWithContext(ctx, "POST", srv.URL+"/v1/messages", bytes.NewReader(raw))
388		for k, v := range apiHeaders {
389			req.Header.Set(k, v)
390		}
391		resp, err := srv.Client().Do(req)
392		if err != nil {
393			t.Fatal(err)
394		}
395		defer resp.Body.Close()
396		start := time.Now()
397		all, readErr := io.ReadAll(resp.Body)
398		if readErr == nil {
399			t.Fatalf("the stream ended on its own after %v: %s", time.Since(start), all)
400		}
401		if !strings.Contains(string(all), `Mer`) || strings.Contains(string(all), "message_stop") {
402			t.Errorf("stalled stream sent %q; want the prefix and no message_stop", all)
403		}
404		done := make(chan struct{})
405		go func() { srv.Close(); close(done) }()
406		select {
407		case <-done:
408		case <-time.After(3 * time.Second):
409			t.Fatal("server shutdown blocked on the stalled handler")
410		}
411	}
