539	// The mock is used through the real SDK in internal/llm. This checks the SDK
540	// accumulates a mock stream into a full message and maps a mock error to its
541	// typed error.
542	func TestThroughRealSDK(t *testing.T) {
543		m, srv := serve(t, mockllm.Options{})
544		answer := `{"sms":{"body":"Merhaba {{first_name}} {{campaign_url}}"},"email":{"subject":"Sepet","body":"Selam"}}`
545		m.Script(mockllm.Content, mockllm.Reply{Text: answer}, mockllm.Status(529))
546		s, err := schemas(t).ForAPI(schema.Content)
547		if err != nil {
548			t.Fatal(err)
549		}
550		client := anthropic.NewClient(option.WithBaseURL(srv.URL), option.WithAPIKey("mock-placeholder"), option.WithMaxRetries(0))
551		params := anthropic.MessageNewParams{
552			Model:     "claude-opus-5-5",
553			MaxTokens: 4096,
554			Messages:  []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock("<brief>b</brief>"))},
555		}
556		format := option.WithJSONSet("output_config", map[string]any{"effort": "medium", "format": map[string]any{"type": "json_schema", "schema": s}})
557		ctx := context.Background()
558	
559		stream := client.Messages.NewStreaming(ctx, params, format)
560		msg := anthropic.Message{}
561		for stream.Next() {
562			if err := msg.Accumulate(stream.Current()); err != nil {
563				t.Fatal(err)
564			}
565		}
566		if err := stream.Err(); err != nil {
567			t.Fatal(err)
568		}
569		var got string
570		for _, b := range msg.Content {
571			if tb, ok := b.AsAny().(anthropic.TextBlock); ok {
572				got += tb.Text
573			}
574		}
575		if got != answer || msg.StopReason != anthropic.StopReasonEndTurn {
576			t.Errorf("accumulated %q (stop %q), want %q", got, msg.StopReason, answer)
577		}
578	
579		_, err = client.Messages.New(ctx, params, format)
580		var apiErr *anthropic.Error
581		if !errors.As(err, &apiErr) || apiErr.StatusCode != 529 {
582			t.Errorf("529 through the SDK: %v", err)
583		}
584		if n := len(m.Requests()); n != 2 {
585			t.Errorf("%d requests; the SDK retried despite WithMaxRetries(0)", n)
586		}
587	}
