47		t.Helper()
48		a := &fakeAPI{}
49		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
50			raw, _ := io.ReadAll(r.Body)
51			var body map[string]any
52			_ = json.Unmarshal(raw, &body)
53			a.mu.Lock()
54			n := len(a.bodies)
55			a.bodies = append(a.bodies, body)
56			a.headers = append(a.headers, r.Header.Clone())
57			a.paths = append(a.paths, r.URL.Path)
58			a.mu.Unlock()
59			handle(n, w, r)
60		}))
61		t.Cleanup(srv.Close)
62		return a, srv
63	}
