75	// streamStart writes the events before the first text delta: message_start
76	// and an empty thinking block with a signature, as Opus 5.5 sends them.
77	func streamStart(w http.ResponseWriter, sig string) {
78		w.Header().Set("Content-Type", "text/event-stream")
79		w.WriteHeader(http.StatusOK)
80		event(w, "message_start", `{"type":"message_start","message":{"id":"msg_test","type":"message","role":"assistant","model":"claude-opus-5-5","content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":42,"output_tokens":1}}}`)
81		event(w, "content_block_start", `{"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":"","signature":""}}`)
82		event(w, "content_block_delta", `{"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":`+js(sig)+`}}`)
83		event(w, "content_block_stop", `{"type":"content_block_stop","index":0}`)
84		event(w, "content_block_start", `{"type":"content_block_start","index":1,"content_block":{"type":"text","text":""}}`)
85	}
86	
87	func textDelta(w http.ResponseWriter, chunk string) {
88		event(w, "content_block_delta", `{"type":"content_block_delta","index":1,"delta":{"type":"text_delta","text":`+js(chunk)+`}}`)
89	}
