91	// writeStream writes a whole streamed answer.
92	func writeStream(w http.ResponseWriter, sig, stop string, chunks ...string) {
93		streamStart(w, sig)
94		for _, c := range chunks {
95			textDelta(w, c)
96		}
97		event(w, "content_block_stop", `{"type":"content_block_stop","index":1}`)
98		event(w, "message_delta", `{"type":"message_delta","delta":{"stop_reason":`+js(stop)+`,"stop_sequence":null},"usage":{"output_tokens":17}}`)
99		event(w, "message_stop", `{"type":"message_stop"}`)
100	}
