130	// systemText reads the system prompt, sent as a string or as text blocks.
131	func systemText(body map[string]any) string {
132		switch s := body["system"].(type) {
133		case string:
134			return s
135		case []any:
136			var sb strings.Builder
137			for _, b := range s {
138				if m, ok := b.(map[string]any); ok {
139					t, _ := m["text"].(string)
140					sb.WriteString(t)
141				}
142			}
143			return sb.String()
144		}
145		return ""
146	}
