148	func messages(body map[string]any) []map[string]any {
149		list, _ := body["messages"].([]any)
150		var out []map[string]any
151		for _, m := range list {
152			mm, _ := m.(map[string]any)
153			out = append(out, mm)
154		}
155		return out
