158	// blocks reads a message's content as blocks; a plain string is one text block.
159	func blocks(m map[string]any) []map[string]any {
160		switch c := m["content"].(type) {
161		case string:
162			return []map[string]any{{"type": "text", "text": c}}
163		case []any:
164			var out []map[string]any
165			for _, b := range c {
166				bm, _ := b.(map[string]any)
167				out = append(out, bm)
168			}
169			return out
170		}
171		return nil
172	}
