174	func messageText(m map[string]any) string {
175		var sb strings.Builder
176		for _, b := range blocks(m) {
177			if b["type"] == "text" {
178				s, _ := b["text"].(string)
179				sb.WriteString(s)
180			}
181		}
182		return sb.String()
183	}
