200	// TestRequestShape pins what goes over the wire for each stage: model,
201	// adaptive thinking, explicit effort, JSON outputs with the API-derived
202	// schema, streaming, the refusal fallback, and nothing the API rejects.
203	func TestRequestShape(t *testing.T) {
204		set := schemas(t)
205		cases := []struct {
206			stage  Stage
207			name   schema.Name
208			effort string
209		}{
210			{Segment, schema.SegmentRule, "low"},
211			{Content, schema.Content, "medium"},
212		}
213		for _, c := range cases {
214			api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", `{}`) })
215			cl := testClient(t, srv.URL, nil)
216			if _, err := cl.Call(context.Background(), NewConversation(c.stage, "first turn"), nil); err != nil {
217				t.Fatalf("%s: %v", c.stage, err)
218			}
219			if api.count() != 1 {
220				t.Fatalf("%s: %d requests, want 1", c.stage, api.count())
221			}
222			body, h := api.body(0), api.headers[0]
223			if !strings.HasPrefix(api.paths[0], "/v1/messages") {
224				t.Errorf("%s: path %q", c.stage, api.paths[0])
225			}
226			if body["model"] != DefaultModel {
227				t.Errorf("%s: model %v, want %s", c.stage, body["model"], DefaultModel)
228			}
229			if body["stream"] != true {
230				t.Errorf("%s: stream = %v, want true", c.stage, body["stream"])
231			}
232			if mt, _ := body["max_tokens"].(float64); mt <= 0 {
233				t.Errorf("%s: max_tokens %v", c.stage, body["max_tokens"])
234			}
235			if th, _ := body["thinking"].(map[string]any); th["type"] != "adaptive" {
236				t.Errorf("%s: thinking %v, want adaptive (Opus 5.5 cannot disable it)", c.stage, body["thinking"])
237			}
238			oc, _ := body["output_config"].(map[string]any)
239			if oc["effort"] != c.effort {
240				t.Errorf("%s: effort %v, want %s set explicitly", c.stage, oc["effort"], c.effort)
241			}
242			format, _ := oc["format"].(map[string]any)
243			if format["type"] != "json_schema" {
244				t.Errorf("%s: output_config.format %v, want json_schema", c.stage, format)
245			}
246			want, err := set.ForAPI(c.name)
247			if err != nil {
248				t.Fatal(err)
249			}
250			if !reflect.DeepEqual(normalize(t, format["schema"]), normalize(t, want)) {
251				t.Errorf("%s: the schema sent is not schema.ForAPI(%s)", c.stage, c.name)
252			}
253			for _, banned := range []string{"temperature", "top_p", "top_k", "tools", "tool_choice"} {
254				if _, ok := body[banned]; ok {
255					t.Errorf("%s: request has %q", c.stage, banned)
256				}
257			}
258			if body["fallbacks"] != "default" {
259				t.Errorf("%s: fallbacks %v, want \"default\"", c.stage, body["fallbacks"])
260			}
261			if !strings.Contains(strings.Join(h.Values("anthropic-beta"), ","), FallbackBeta) {
262				t.Errorf("%s: anthropic-beta %q lacks %s", c.stage, h.Values("anthropic-beta"), FallbackBeta)
263			}
264			if h.Get("x-api-key") != "test-placeholder" || h.Get("anthropic-version") == "" {
265				t.Errorf("%s: auth headers %v", c.stage, h)
266			}
267			if got := systemText(body); !strings.Contains(got, SystemPrompt(c.stage)) {
268				t.Errorf("%s: system prompt not sent", c.stage)
269			}
270			msgs := messages(body)
271			if len(msgs) != 1 || msgs[0]["role"] != "user" || messageText(msgs[0]) != "first turn" {
272				t.Errorf("%s: messages %v", c.stage, msgs)
273			}
274		}
275	}
