355			after      time.Duration
356		}{
357			{"500", 500, "api_error", "internal", "", retry.ServerError, 0},
358			{"529 overloaded", 529, "overloaded_error", "Overloaded", "", retry.ServerError, 0},
359			{"429", 429, "rate_limit_error", "slow down", "7", retry.RateLimited, 7 * time.Second},
360			{"408", 408, "timeout_error", "timeout", "", retry.Timeout, 0},
361			{"400", 400, "invalid_request_error", "temperature is not supported on this model", "", retry.ClientError, 0},
362			{"401", 401, "authentication_error", "invalid x-api-key", "", retry.ClientError, 0},
363		}
