366				if c.retryAfter != "" {
367					w.Header().Set("Retry-After", c.retryAfter)
368				}
369				apiError(w, c.status, c.typ, c.msg)
370			})
371			_, err := testClient(t, srv.URL, nil).Call(context.Background(), NewConversation(Segment, "x"), nil)
372			var ce *CallError
373			if !errors.As(err, &ce) {
374				t.Errorf("%s: error %v, want *CallError", c.name, err)
