403	// The watchdog cancels a stream with no event for StallTimeout, including
404	// the wait for the response headers, and any stream older than TotalTimeout.
405	func TestWatchdog(t *testing.T) {
406		release := make(chan struct{})
407		t.Cleanup(func() { close(release) })
408		wait := func(r *http.Request) {
409			select {
410			case <-r.Context().Done():
411			case <-release:
412			}
413		}
414		cases := []struct {
415			name         string
416			stall, total time.Duration
417			handle       func(w http.ResponseWriter, r *http.Request)
418			want         error
419			deltas       int
420		}{
421			{"stall mid-stream", 150 * time.Millisecond, 10 * time.Second, func(w http.ResponseWriter, r *http.Request) {
422				streamStart(w, "sig")
423				textDelta(w, `{"sms":{"body":"Mer`)
424				wait(r)
425			}, ErrStalled, 1},
426			{"stall before headers", 150 * time.Millisecond, 10 * time.Second, func(_ http.ResponseWriter, r *http.Request) { wait(r) }, ErrStalled, 0},
427			{"total timeout with pings", 2 * time.Second, 300 * time.Millisecond, func(w http.ResponseWriter, r *http.Request) {
428				streamStart(w, "sig")
429				for {
430					select {
431					case <-r.Context().Done():
432						return
433					case <-release:
434						return
435					case <-time.After(20 * time.Millisecond):
436						event(w, "ping", `{"type":"ping"}`)
437					}
438				}
439			}, ErrTotalTimeout, 0},
440		}
441		for _, c := range cases {
442			_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, r *http.Request) { c.handle(w, r) })
443			cl := testClient(t, srv.URL, func(cfg *Config) { cfg.StallTimeout, cfg.TotalTimeout = c.stall, c.total })
444			var deltas int
445			start := time.Now()
446			_, err := cl.Call(context.Background(), NewConversation(Content, "x"), func(string) { deltas++ })
447			if took := time.Since(start); took > 3*time.Second {
448				t.Errorf("%s: took %v; the watchdog did not fire", c.name, took)
449			}
450			if !errors.Is(err, c.want) {
451				t.Errorf("%s: error %v, want %v", c.name, err, c.want)
452			}
453			var ce *CallError
454			if !errors.As(err, &ce) || ce.Class != retry.Timeout {
455				t.Errorf("%s: error %v, want a CallError with class timeout so it is retried", c.name, err)
456			}
457			if deltas != c.deltas {
458				t.Errorf("%s: %d deltas before the stall, want %d", c.name, deltas, c.deltas)
459			}
460		}
461		if DefaultStallTimeout != 20*time.Second || DefaultTotalTimeout != 120*time.Second {
462			t.Errorf("defaults %v and %v, want 20s and 120s", DefaultStallTimeout, DefaultTotalTimeout)
463		}
464	}
