466	// The repair turn is append-only (preserved thinking on Opus 5.5 forbids
467	// editing earlier turns): the earlier messages are resent byte for byte, the
468	// assistant turn goes back unchanged with its thinking block, and the next
469	// user turn carries the validation errors as JSON.
470	func TestRepairTurn(t *testing.T) {
471		answers := []string{`{"sms":{"body":"Hi {{password}}"}}`, `{"sms":{"body":"Hi {{first_name}}"}}`, `{}`}
472		api, srv := newFakeAPI(t, func(n int, w http.ResponseWriter, _ *http.Request) {
473			writeStream(w, fmt.Sprintf("sig-%d", n+1), "end_turn", answers[n])
474		})
475		cl := testClient(t, srv.URL, nil)
476		conv := NewConversation(Content, "first turn")
477		ctx := context.Background()
478	
479		r1, err := cl.Call(ctx, conv, nil)
480		if err != nil {
481			t.Fatal(err)
482		}
483		issues1 := []validation.Issue{
484			{Path: "/sms/body", Code: validation.UnknownVariable, Message: `variable "password" is not allowed`},
485			{Path: "/email", Code: validation.Required, Message: `missing required key "email"`},
486		}
487		conv.Repair(r1, issues1)
488		r2, err := cl.Call(ctx, conv, nil)
489		if err != nil {
490			t.Fatal(err)
491		}
492		issues2 := []validation.Issue{{Path: "/email", Code: validation.Required, Message: `missing required key "email"`}}
493		conv.Repair(r2, issues2)
494		if _, err := cl.Call(ctx, conv, nil); err != nil {
495			t.Fatal(err)
496		}
497	
498		b1, b2, b3 := api.body(0), api.body(1), api.body(2)
499		m1, m2, m3 := messages(b1), messages(b2), messages(b3)
500		if len(m1) != 1 || len(m2) != 3 || len(m3) != 5 {
501			t.Fatalf("message counts %d, %d, %d; want 1, 3, 5", len(m1), len(m2), len(m3))
502		}
503		if !reflect.DeepEqual(m2[:1], m1) || !reflect.DeepEqual(m3[:3], m2) {
504			t.Error("an earlier turn was changed; the conversation must be append-only")
505		}
506		checkAssistant(t, m2[1], "sig-1", answers[0])
507		checkAssistant(t, m3[3], "sig-2", answers[1])
508		checkRepairErrors(t, m2[2], issues1)
509		checkRepairErrors(t, m3[4], issues2)
510		// The cached prefix stays the same across attempts.
511		for _, k := range []string{"system", "output_config", "model", "thinking"} {
512			if !reflect.DeepEqual(b1[k], b2[k]) || !reflect.DeepEqual(b2[k], b3[k]) {
513				t.Errorf("%s changed between attempts", k)
514			}
515		}
516	}
