518	func checkAssistant(t *testing.T, m map[string]any, sig, text string) {
519		t.Helper()
520		if m["role"] != "assistant" {
521			t.Fatalf("role %v, want assistant", m["role"])
522		}
523		var gotSig, gotText []string
524		for _, b := range blocks(m) {
525			switch b["type"] {
526			case "thinking":
527				s, _ := b["signature"].(string)
528				gotSig = append(gotSig, s)
529				if th, _ := b["thinking"].(string); th != "" {
530					t.Errorf("thinking text %q, want the empty text that was received", th)
531				}
532			case "text":
533				s, _ := b["text"].(string)
534				gotText = append(gotText, s)
535			}
536		}
537		if !slices.Equal(gotSig, []string{sig}) || !slices.Equal(gotText, []string{text}) {
538			t.Errorf("assistant turn: thinking signatures %q, texts %q; want [%s] and [%s] unchanged", gotSig, gotText, sig, text)
539		}
540	}
