542	// checkRepairErrors finds the JSON array in the user turn and requires it to
543	// be exactly the validation issues.
544	func checkRepairErrors(t *testing.T, m map[string]any, want []validation.Issue) {
545		t.Helper()
546		if m["role"] != "user" {
547			t.Fatalf("role %v, want user", m["role"])
548		}
549		text := messageText(m)
550		i, j := strings.Index(text, "["), strings.LastIndex(text, "]")
551		if i < 0 || j < i {
552			t.Fatalf("repair turn has no JSON array: %q", text)
553		}
554		var got []validation.Issue
555		if err := json.Unmarshal([]byte(text[i:j+1]), &got); err != nil {
556			t.Fatalf("repair turn errors are not JSON: %v: %q", err, text)
557		}
558		if !reflect.DeepEqual(got, want) {
559			t.Errorf("repair turn errors %+v, want %+v", got, want)
560		}
561	}
562	
563	// ConfigFromEnv fails closed. Mock mode never reads the API key, so a
564	// misconfigured worker cannot send it to the mock.
565	func TestConfigFromEnv(t *testing.T) {
566		run := func(env map[string]string) (Config, []string, error) {
567			var asked []string
568			cfg, err := ConfigFromEnv(func(k string) string {
569				asked = append(asked, k)
570				return env[k]
571			})
572			return cfg, asked, err
573		}
574		cfg, asked, err := run(map[string]string{"LLM_MODE": "mock", "ANTHROPIC_API_KEY": "must-not-be-read", "ANTHROPIC_AUTH_TOKEN": "must-not-be-read"})
575		if err != nil || cfg.BaseURL != MockBaseURL || cfg.APIKey == "" || cfg.APIKey == "must-not-be-read" || cfg.Model != DefaultModel {
576			t.Errorf("mock mode: %+v %v", cfg, err)
577		}
578		if slices.Contains(asked, "ANTHROPIC_API_KEY") || slices.Contains(asked, "ANTHROPIC_AUTH_TOKEN") {
579			t.Errorf("mock mode read the key: asked %v", asked)
580		}
581		cfg, _, err = run(map[string]string{"LLM_MODE": "mock", "MOCKLLM_URL": "http://127.0.0.1:8090", "ANTHROPIC_MODEL": "claude-test-model"})
582		if err != nil || cfg.BaseURL != "http://127.0.0.1:8090" || cfg.Model != "claude-test-model" {
583			t.Errorf("mock mode with overrides: %+v %v", cfg, err)
584		}
585		if _, _, err := run(map[string]string{"LLM_MODE": "anthropic"}); !errors.Is(err, ErrNoAPIKey) {
586			t.Errorf("anthropic mode without a key: %v, want ErrNoAPIKey", err)
587		}
588		cfg, _, err = run(map[string]string{"LLM_MODE": "anthropic", "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"})
589		if err != nil || cfg.APIKey != "placeholder-not-a-real-key" || cfg.BaseURL != "" || cfg.Model != DefaultModel {
590			t.Errorf("anthropic mode: BaseURL %q, Model %q, key set %v, err %v", cfg.BaseURL, cfg.Model, cfg.APIKey != "", err)
591		}
592		for _, mode := range []string{"", "Mock", "openai", "real"} {
593			if _, _, err := run(map[string]string{"LLM_MODE": mode, "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"}); !errors.Is(err, ErrUnknownMode) {
594				t.Errorf("LLM_MODE=%q: %v, want ErrUnknownMode", mode, err)
595			}
596		}
597	}
