package llm

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"reflect"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/retry"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// fakeAPI records every request and answers with handle. These tests use
// their own tiny server rather than internal/mockllm, so the client's
// contract is pinned independently of the mock.
type fakeAPI struct {
	mu      sync.Mutex
	bodies  []map[string]any
	headers []http.Header
	paths   []string
}

func (a *fakeAPI) count() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return len(a.bodies)
}

func (a *fakeAPI) body(i int) map[string]any {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.bodies[i]
}

func newFakeAPI(t *testing.T, handle func(n int, w http.ResponseWriter, r *http.Request)) (*fakeAPI, *httptest.Server) {
	t.Helper()
	a := &fakeAPI{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		var body map[string]any
		_ = json.Unmarshal(raw, &body)
		a.mu.Lock()
		n := len(a.bodies)
		a.bodies = append(a.bodies, body)
		a.headers = append(a.headers, r.Header.Clone())
		a.paths = append(a.paths, r.URL.Path)
		a.mu.Unlock()
		handle(n, w, r)
	}))
	t.Cleanup(srv.Close)
	return a, srv
}

func js(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func event(w http.ResponseWriter, name, data string) {
	fmt.Fprintf(w, "event: %s\ndata: %s\n\n", name, data)
	w.(http.Flusher).Flush()
}

// streamStart writes the events before the first text delta: message_start
// and an empty thinking block with a signature, as Opus 5.5 sends them.
func streamStart(w http.ResponseWriter, sig string) {
	w.Header().Set("Content-Type", "text/event-stream")
	w.WriteHeader(http.StatusOK)
	event(w, "message_start", `{"type":"message_start","message":{"id":"msg_test","type":"message","role":"assistant","model":"claude-opus-5-5","content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":42,"output_tokens":1}}}`)
	event(w, "content_block_start", `{"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":"","signature":""}}`)
	event(w, "content_block_delta", `{"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":`+js(sig)+`}}`)
	event(w, "content_block_stop", `{"type":"content_block_stop","index":0}`)
	event(w, "content_block_start", `{"type":"content_block_start","index":1,"content_block":{"type":"text","text":""}}`)
}

func textDelta(w http.ResponseWriter, chunk string) {
	event(w, "content_block_delta", `{"type":"content_block_delta","index":1,"delta":{"type":"text_delta","text":`+js(chunk)+`}}`)
}

// writeStream writes a whole streamed answer.
func writeStream(w http.ResponseWriter, sig, stop string, chunks ...string) {
	streamStart(w, sig)
	for _, c := range chunks {
		textDelta(w, c)
	}
	event(w, "content_block_stop", `{"type":"content_block_stop","index":1}`)
	event(w, "message_delta", `{"type":"message_delta","delta":{"stop_reason":`+js(stop)+`,"stop_sequence":null},"usage":{"output_tokens":17}}`)
	event(w, "message_stop", `{"type":"message_stop"}`)
}

func apiError(w http.ResponseWriter, status int, typ, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	fmt.Fprintf(w, `{"type":"error","error":{"type":%s,"message":%s}}`, js(typ), js(msg))
}

func schemas(t *testing.T) *schema.Set {
	t.Helper()
	set, err := schema.Load()
	if err != nil {
		t.Fatal(err)
	}
	return set
}

func testClient(t *testing.T, baseURL string, mod func(*Config)) *Client {
	t.Helper()
	cfg := Config{BaseURL: baseURL, APIKey: "test-placeholder", Schemas: schemas(t), StallTimeout: 5 * time.Second, TotalTimeout: 10 * time.Second}
	if mod != nil {
		mod(&cfg)
	}
	c, err := New(cfg)
	if err != nil {
		t.Fatal(err)
	}
	return c
}

// systemText reads the system prompt, sent as a string or as text blocks.
func systemText(body map[string]any) string {
	switch s := body["system"].(type) {
	case string:
		return s
	case []any:
		var sb strings.Builder
		for _, b := range s {
			if m, ok := b.(map[string]any); ok {
				t, _ := m["text"].(string)
				sb.WriteString(t)
			}
		}
		return sb.String()
	}
	return ""
}

func messages(body map[string]any) []map[string]any {
	list, _ := body["messages"].([]any)
	var out []map[string]any
	for _, m := range list {
		mm, _ := m.(map[string]any)
		out = append(out, mm)
	}
	return out
}

// blocks reads a message's content as blocks; a plain string is one text block.
func blocks(m map[string]any) []map[string]any {
	switch c := m["content"].(type) {
	case string:
		return []map[string]any{{"type": "text", "text": c}}
	case []any:
		var out []map[string]any
		for _, b := range c {
			bm, _ := b.(map[string]any)
			out = append(out, bm)
		}
		return out
	}
	return nil
}

func messageText(m map[string]any) string {
	var sb strings.Builder
	for _, b := range blocks(m) {
		if b["type"] == "text" {
			s, _ := b["text"].(string)
			sb.WriteString(s)
		}
	}
	return sb.String()
}

// normalize round-trips a value through encoding/json, so two decoded
// schemas compare equal whatever number types they used.
func normalize(t *testing.T, v any) any {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

// TestRequestShape pins what goes over the wire for each stage: model,
// adaptive thinking, explicit effort, JSON outputs with the API-derived
// schema, streaming, the refusal fallback, and nothing the API rejects.
func TestRequestShape(t *testing.T) {
	set := schemas(t)
	cases := []struct {
		stage  Stage
		name   schema.Name
		effort string
	}{
		{Segment, schema.SegmentRule, "low"},
		{Content, schema.Content, "medium"},
	}
	for _, c := range cases {
		api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", `{}`) })
		cl := testClient(t, srv.URL, nil)
		if _, err := cl.Call(context.Background(), NewConversation(c.stage, "first turn"), nil); err != nil {
			t.Fatalf("%s: %v", c.stage, err)
		}
		if api.count() != 1 {
			t.Fatalf("%s: %d requests, want 1", c.stage, api.count())
		}
		body, h := api.body(0), api.headers[0]
		if !strings.HasPrefix(api.paths[0], "/v1/messages") {
			t.Errorf("%s: path %q", c.stage, api.paths[0])
		}
		if body["model"] != DefaultModel {
			t.Errorf("%s: model %v, want %s", c.stage, body["model"], DefaultModel)
		}
		if body["stream"] != true {
			t.Errorf("%s: stream = %v, want true", c.stage, body["stream"])
		}
		if mt, _ := body["max_tokens"].(float64); mt <= 0 {
			t.Errorf("%s: max_tokens %v", c.stage, body["max_tokens"])
		}
		if th, _ := body["thinking"].(map[string]any); th["type"] != "adaptive" {
			t.Errorf("%s: thinking %v, want adaptive (Opus 5.5 cannot disable it)", c.stage, body["thinking"])
		}
		oc, _ := body["output_config"].(map[string]any)
		if oc["effort"] != c.effort {
			t.Errorf("%s: effort %v, want %s set explicitly", c.stage, oc["effort"], c.effort)
		}
		format, _ := oc["format"].(map[string]any)
		if format["type"] != "json_schema" {
			t.Errorf("%s: output_config.format %v, want json_schema", c.stage, format)
		}
		want, err := set.ForAPI(c.name)
		if err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(normalize(t, format["schema"]), normalize(t, want)) {
			t.Errorf("%s: the schema sent is not schema.ForAPI(%s)", c.stage, c.name)
		}
		for _, banned := range []string{"temperature", "top_p", "top_k", "tools", "tool_choice"} {
			if _, ok := body[banned]; ok {
				t.Errorf("%s: request has %q", c.stage, banned)
			}
		}
		if body["fallbacks"] != "default" {
			t.Errorf("%s: fallbacks %v, want \"default\"", c.stage, body["fallbacks"])
		}
		if !strings.Contains(strings.Join(h.Values("anthropic-beta"), ","), FallbackBeta) {
			t.Errorf("%s: anthropic-beta %q lacks %s", c.stage, h.Values("anthropic-beta"), FallbackBeta)
		}
		if h.Get("x-api-key") != "test-placeholder" || h.Get("anthropic-version") == "" {
			t.Errorf("%s: auth headers %v", c.stage, h)
		}
		if got := systemText(body); !strings.Contains(got, SystemPrompt(c.stage)) {
			t.Errorf("%s: system prompt not sent", c.stage)
		}
		msgs := messages(body)
		if len(msgs) != 1 || msgs[0]["role"] != "user" || messageText(msgs[0]) != "first turn" {
			t.Errorf("%s: messages %v", c.stage, msgs)
		}
	}
}

func TestModelFromConfig(t *testing.T) {
	api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", `{}`) })
	cl := testClient(t, srv.URL, func(c *Config) { c.Model = "claude-test-model" })
	if _, err := cl.Call(context.Background(), NewConversation(Segment, "x"), nil); err != nil {
		t.Fatal(err)
	}
	if api.body(0)["model"] != "claude-test-model" || cl.Model() != "claude-test-model" {
		t.Errorf("model %v, Model() %q", api.body(0)["model"], cl.Model())
	}
}

// The SDK reads credentials and the base URL from the environment by
// default. The client must use only its Config, so a key in the environment
// can never reach the mock, and mock mode can never reach the real API.
func TestClientIgnoresSDKEnvironment(t *testing.T) {
	t.Setenv("ANTHROPIC_API_KEY", "env-value-must-not-be-sent")
	t.Setenv("ANTHROPIC_AUTH_TOKEN", "env-token-must-not-be-sent")
	t.Setenv("ANTHROPIC_BASE_URL", "http://127.0.0.1:9")
	api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", `{}`) })
	cl := testClient(t, srv.URL, nil)
	if _, err := cl.Call(context.Background(), NewConversation(Segment, "x"), nil); err != nil {
		t.Fatalf("the request did not reach Config.BaseURL: %v", err)
	}
	h := api.headers[0]
	if h.Get("x-api-key") != "test-placeholder" || h.Get("Authorization") != "" {
		t.Errorf("credentials from the environment were sent: x-api-key %q, Authorization %q", h.Get("x-api-key"), h.Get("Authorization"))
	}
}

func TestNewNeedsSchemas(t *testing.T) {
	if _, err := New(Config{BaseURL: "http://127.0.0.1:9", APIKey: "x"}); err == nil {
		t.Error("New without Schemas succeeded; the output format could not be built")
	}
}

// Text deltas reach onText as they arrive; thinking does not. Stop reason,
// usage and latency are captured.
func TestStreamingResponse(t *testing.T) {
	chunks := []string{`{"sms":`, `{"body":"Mer`, `haba"}}`}
	_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", "end_turn", chunks...) })
	cl := testClient(t, srv.URL, nil)
	var got []string
	resp, err := cl.Call(context.Background(), NewConversation(Content, "x"), func(d string) { got = append(got, d) })
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Equal(got, chunks) {
		t.Errorf("deltas %q, want %q", got, chunks)
	}
	if resp.Text != strings.Join(chunks, "") || resp.StopReason != "end_turn" || resp.Model != "claude-opus-5-5" {
		t.Errorf("response %+v", resp)
	}
	if resp.InputTokens != 42 || resp.OutputTokens != 17 || resp.Latency <= 0 {
		t.Errorf("usage %d in, %d out, latency %v", resp.InputTokens, resp.OutputTokens, resp.Latency)
	}
}

// A refusal or max_tokens is a complete HTTP exchange, not a transport
// error. The caller decides: a refusal is never retried, max_tokens is.
func TestStopReasonsAreNotErrors(t *testing.T) {
	for _, stop := range []string{"refusal", "max_tokens"} {
		_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) { writeStream(w, "sig", stop, `{"sms":{"bo`) })
		resp, err := testClient(t, srv.URL, nil).Call(context.Background(), NewConversation(Content, "x"), nil)
		if err != nil || resp.StopReason != stop {
			t.Errorf("%s: resp %+v, err %v", stop, resp, err)
		}
	}
}

// SDK retries are off: every retry goes through internal/retry. A failing
// call is classified, and the API's error message is kept for llm_calls.
func TestErrorsAreClassifiedAndNotRetried(t *testing.T) {
	cases := []struct {
		name       string
		status     int
		typ, msg   string
		retryAfter string
		class      retry.Class
		after      time.Duration
	}{
		{"500", 500, "api_error", "internal", "", retry.ServerError, 0},
		{"529 overloaded", 529, "overloaded_error", "Overloaded", "", retry.ServerError, 0},
		{"429", 429, "rate_limit_error", "slow down", "7", retry.RateLimited, 7 * time.Second},
		{"408", 408, "timeout_error", "timeout", "", retry.Timeout, 0},
		{"400", 400, "invalid_request_error", "temperature is not supported on this model", "", retry.ClientError, 0},
		{"401", 401, "authentication_error", "invalid x-api-key", "", retry.ClientError, 0},
	}
	for _, c := range cases {
		api, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, _ *http.Request) {
			if c.retryAfter != "" {
				w.Header().Set("Retry-After", c.retryAfter)
			}
			apiError(w, c.status, c.typ, c.msg)
		})
		_, err := testClient(t, srv.URL, nil).Call(context.Background(), NewConversation(Segment, "x"), nil)
		var ce *CallError
		if !errors.As(err, &ce) {
			t.Errorf("%s: error %v, want *CallError", c.name, err)
			continue
		}
		if ce.Status != c.status || ce.Class != c.class || ce.RetryAfter != c.after {
			t.Errorf("%s: %+v, want status %d class %s retry-after %v", c.name, ce, c.status, c.class, c.after)
		}
		if !strings.Contains(err.Error(), c.msg) {
			t.Errorf("%s: error %q lacks the API message %q", c.name, err, c.msg)
		}
		if api.count() != 1 {
			t.Errorf("%s: %d requests; the SDK retried on its own", c.name, api.count())
		}
	}
}

func TestConnectionRefused(t *testing.T) {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := l.Addr().String()
	l.Close()
	_, err = testClient(t, "http://"+addr, nil).Call(context.Background(), NewConversation(Segment, "x"), nil)
	var ce *CallError
	if !errors.As(err, &ce) || ce.Class != retry.ConnRefused || ce.Status != 0 {
		t.Errorf("error %v, want a CallError with class conn_refused", err)
	}
}

// The watchdog cancels a stream with no event for StallTimeout, including
// the wait for the response headers, and any stream older than TotalTimeout.
func TestWatchdog(t *testing.T) {
	release := make(chan struct{})
	t.Cleanup(func() { close(release) })
	wait := func(r *http.Request) {
		select {
		case <-r.Context().Done():
		case <-release:
		}
	}
	cases := []struct {
		name         string
		stall, total time.Duration
		handle       func(w http.ResponseWriter, r *http.Request)
		want         error
		deltas       int
	}{
		{"stall mid-stream", 150 * time.Millisecond, 10 * time.Second, func(w http.ResponseWriter, r *http.Request) {
			streamStart(w, "sig")
			textDelta(w, `{"sms":{"body":"Mer`)
			wait(r)
		}, ErrStalled, 1},
		{"stall before headers", 150 * time.Millisecond, 10 * time.Second, func(_ http.ResponseWriter, r *http.Request) { wait(r) }, ErrStalled, 0},
		{"total timeout with pings", 2 * time.Second, 300 * time.Millisecond, func(w http.ResponseWriter, r *http.Request) {
			streamStart(w, "sig")
			for {
				select {
				case <-r.Context().Done():
					return
				case <-release:
					return
				case <-time.After(20 * time.Millisecond):
					event(w, "ping", `{"type":"ping"}`)
				}
			}
		}, ErrTotalTimeout, 0},
	}
	for _, c := range cases {
		_, srv := newFakeAPI(t, func(_ int, w http.ResponseWriter, r *http.Request) { c.handle(w, r) })
		cl := testClient(t, srv.URL, func(cfg *Config) { cfg.StallTimeout, cfg.TotalTimeout = c.stall, c.total })
		var deltas int
		start := time.Now()
		_, err := cl.Call(context.Background(), NewConversation(Content, "x"), func(string) { deltas++ })
		if took := time.Since(start); took > 3*time.Second {
			t.Errorf("%s: took %v; the watchdog did not fire", c.name, took)
		}
		if !errors.Is(err, c.want) {
			t.Errorf("%s: error %v, want %v", c.name, err, c.want)
		}
		var ce *CallError
		if !errors.As(err, &ce) || ce.Class != retry.Timeout {
			t.Errorf("%s: error %v, want a CallError with class timeout so it is retried", c.name, err)
		}
		if deltas != c.deltas {
			t.Errorf("%s: %d deltas before the stall, want %d", c.name, deltas, c.deltas)
		}
	}
	if DefaultStallTimeout != 20*time.Second || DefaultTotalTimeout != 120*time.Second {
		t.Errorf("defaults %v and %v, want 20s and 120s", DefaultStallTimeout, DefaultTotalTimeout)
	}
}

// The repair turn is append-only (preserved thinking on Opus 5.5 forbids
// editing earlier turns): the earlier messages are resent byte for byte, the
// assistant turn goes back unchanged with its thinking block, and the next
// user turn carries the validation errors as JSON.
func TestRepairTurn(t *testing.T) {
	answers := []string{`{"sms":{"body":"Hi {{password}}"}}`, `{"sms":{"body":"Hi {{first_name}}"}}`, `{}`}
	api, srv := newFakeAPI(t, func(n int, w http.ResponseWriter, _ *http.Request) {
		writeStream(w, fmt.Sprintf("sig-%d", n+1), "end_turn", answers[n])
	})
	cl := testClient(t, srv.URL, nil)
	conv := NewConversation(Content, "first turn")
	ctx := context.Background()

	r1, err := cl.Call(ctx, conv, nil)
	if err != nil {
		t.Fatal(err)
	}
	issues1 := []validation.Issue{
		{Path: "/sms/body", Code: validation.UnknownVariable, Message: `variable "password" is not allowed`},
		{Path: "/email", Code: validation.Required, Message: `missing required key "email"`},
	}
	conv.Repair(r1, issues1)
	r2, err := cl.Call(ctx, conv, nil)
	if err != nil {
		t.Fatal(err)
	}
	issues2 := []validation.Issue{{Path: "/email", Code: validation.Required, Message: `missing required key "email"`}}
	conv.Repair(r2, issues2)
	if _, err := cl.Call(ctx, conv, nil); err != nil {
		t.Fatal(err)
	}

	b1, b2, b3 := api.body(0), api.body(1), api.body(2)
	m1, m2, m3 := messages(b1), messages(b2), messages(b3)
	if len(m1) != 1 || len(m2) != 3 || len(m3) != 5 {
		t.Fatalf("message counts %d, %d, %d; want 1, 3, 5", len(m1), len(m2), len(m3))
	}
	if !reflect.DeepEqual(m2[:1], m1) || !reflect.DeepEqual(m3[:3], m2) {
		t.Error("an earlier turn was changed; the conversation must be append-only")
	}
	checkAssistant(t, m2[1], "sig-1", answers[0])
	checkAssistant(t, m3[3], "sig-2", answers[1])
	checkRepairErrors(t, m2[2], issues1)
	checkRepairErrors(t, m3[4], issues2)
	// The cached prefix stays the same across attempts.
	for _, k := range []string{"system", "output_config", "model", "thinking"} {
		if !reflect.DeepEqual(b1[k], b2[k]) || !reflect.DeepEqual(b2[k], b3[k]) {
			t.Errorf("%s changed between attempts", k)
		}
	}
}

func checkAssistant(t *testing.T, m map[string]any, sig, text string) {
	t.Helper()
	if m["role"] != "assistant" {
		t.Fatalf("role %v, want assistant", m["role"])
	}
	var gotSig, gotText []string
	for _, b := range blocks(m) {
		switch b["type"] {
		case "thinking":
			s, _ := b["signature"].(string)
			gotSig = append(gotSig, s)
			if th, _ := b["thinking"].(string); th != "" {
				t.Errorf("thinking text %q, want the empty text that was received", th)
			}
		case "text":
			s, _ := b["text"].(string)
			gotText = append(gotText, s)
		}
	}
	if !slices.Equal(gotSig, []string{sig}) || !slices.Equal(gotText, []string{text}) {
		t.Errorf("assistant turn: thinking signatures %q, texts %q; want [%s] and [%s] unchanged", gotSig, gotText, sig, text)
	}
}

// checkRepairErrors finds the JSON array in the user turn and requires it to
// be exactly the validation issues.
func checkRepairErrors(t *testing.T, m map[string]any, want []validation.Issue) {
	t.Helper()
	if m["role"] != "user" {
		t.Fatalf("role %v, want user", m["role"])
	}
	text := messageText(m)
	i, j := strings.Index(text, "["), strings.LastIndex(text, "]")
	if i < 0 || j < i {
		t.Fatalf("repair turn has no JSON array: %q", text)
	}
	var got []validation.Issue
	if err := json.Unmarshal([]byte(text[i:j+1]), &got); err != nil {
		t.Fatalf("repair turn errors are not JSON: %v: %q", err, text)
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("repair turn errors %+v, want %+v", got, want)
	}
}

// ConfigFromEnv fails closed. Mock mode never reads the API key, so a
// misconfigured worker cannot send it to the mock.
func TestConfigFromEnv(t *testing.T) {
	run := func(env map[string]string) (Config, []string, error) {
		var asked []string
		cfg, err := ConfigFromEnv(func(k string) string {
			asked = append(asked, k)
			return env[k]
		})
		return cfg, asked, err
	}
	cfg, asked, err := run(map[string]string{"LLM_MODE": "mock", "ANTHROPIC_API_KEY": "must-not-be-read", "ANTHROPIC_AUTH_TOKEN": "must-not-be-read"})
	if err != nil || cfg.BaseURL != MockBaseURL || cfg.APIKey == "" || cfg.APIKey == "must-not-be-read" || cfg.Model != DefaultModel {
		t.Errorf("mock mode: %+v %v", cfg, err)
	}
	if slices.Contains(asked, "ANTHROPIC_API_KEY") || slices.Contains(asked, "ANTHROPIC_AUTH_TOKEN") {
		t.Errorf("mock mode read the key: asked %v", asked)
	}
	cfg, _, err = run(map[string]string{"LLM_MODE": "mock", "MOCKLLM_URL": "http://127.0.0.1:8090", "ANTHROPIC_MODEL": "claude-test-model"})
	if err != nil || cfg.BaseURL != "http://127.0.0.1:8090" || cfg.Model != "claude-test-model" {
		t.Errorf("mock mode with overrides: %+v %v", cfg, err)
	}
	if _, _, err := run(map[string]string{"LLM_MODE": "anthropic"}); !errors.Is(err, ErrNoAPIKey) {
		t.Errorf("anthropic mode without a key: %v, want ErrNoAPIKey", err)
	}
	cfg, _, err = run(map[string]string{"LLM_MODE": "anthropic", "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"})
	if err != nil || cfg.APIKey != "placeholder-not-a-real-key" || cfg.BaseURL != "" || cfg.Model != DefaultModel {
		t.Errorf("anthropic mode: BaseURL %q, Model %q, key set %v, err %v", cfg.BaseURL, cfg.Model, cfg.APIKey != "", err)
	}
	for _, mode := range []string{"", "Mock", "openai", "real"} {
		if _, _, err := run(map[string]string{"LLM_MODE": mode, "ANTHROPIC_API_KEY": "placeholder-not-a-real-key"}); !errors.Is(err, ErrUnknownMode) {
			t.Errorf("LLM_MODE=%q: %v, want ErrUnknownMode", mode, err)
		}
	}
}

