		var out []map[string]any
		for _, b := range c {
			bm, _ := b.(map[string]any)
			out = append(out, bm)
		}
		return out
	}
	return nil
}

func messageText(m map[string]any) string {
	var sb strings.Builder
	for _, b := range blocks(m) {
		if b["type"] == "text" {
			s, _ := b["text"].(string)
			sb.WriteString(s)
		}
	}
