// Cancel of a sending campaign is the other half of rule 7 in delivery:
// it takes the queued messages out at once (stage 0 implements it; this
// checks the approve-to-cancel path end to end).
func TestApproveThenCancel(t *testing.T) {
	h, p, _ := approveAPI(t)
	id, revs := reviewCampaign(t, p, 0, eligible{10, 5, 5})
	if rec := do(h, "POST", "/api/campaigns/"+id+"/approve", approveBody(revs[0], 0), bearer); rec.Code != http.StatusOK {
		t.Fatalf("approve: %d %s", rec.Code, rec.Body)
	}
	if rec := do(h, "POST", "/api/campaigns/"+id+"/cancel", versionBody(1), bearer); rec.Code != http.StatusOK {
		t.Fatalf("cancel: %d %s", rec.Code, rec.Body)
	}
	if a := loadApproval(t, p, id); a.State != "cancelled" {
		t.Errorf("campaign %s, want cancelled", a.State)
	}
}
