func TestGenerateBackoffDelays(t *testing.T) {
	p, meta := genPool(t)
	g, m, sl := newGen(t, p, meta.AsOf, mockllm.Options{})
	m.Script(mockllm.Content, mockllm.RateLimited("2"), mockllm.Status(529), mockllm.Reply{Text: goodCopy})
