	d := sl.list()
	if len(d) != 2 || d[0] != 2*time.Second || d[1] < 0 || d[1] > 2*retry.BaseDelay {
		t.Errorf("delays %v; want 2s from Retry-After, then a jittered backoff of at most %v", d, 2*retry.BaseDelay)
